window.MG_LAZY_DATA["data/lazy/owner-courses/b269-5c0bbfdf96fd4896.json"]={sha256:"5c0bbfdf96fd48962baba8c192a367b70fc8c88366452c0a94a9386205666bca",value:{"id":"b269","title":"河川水位自動遙測","titleEn":"Automatic river-level telemetry","category":"water","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","summary":"本課將自動水位站拆為基準、感測、取樣、傳輸、率定與電源備援，逐一區分準確度、資料時效及可用性。以李斯渡口和維克斯堡真實站點為背景，所有算例是合成資料；觀測水位、推估流量和警戒決策屬不同層次，必須保留各自假設及品質旗標。","summaryEn":"This course separates automated gaging into datum, sensing, sampling, transmission, rating and power redundancy, distinguishing accuracy, data age and availability. Lees Ferry and Vicksburg provide real station context, while every calculation uses synthetic observations. Measured stage, estimated discharge and warning decisions occupy different layers and require their own assumptions and quality flags.","scope":"依公開工程原理、官方資料與規範架構編寫的原創教學；步驟是可驗證的學習任務與假想算例，不是設計圖說、施工計畫、開挖、注漿或受限空間作業許可，也不是任何專案的設計文件。數值均為教學假設或公開資料，實際工程須由合格技師依規範與實測資料重新計算並簽證。","scopeEn":"Original teaching built from public engineering principles, official sources and code frameworks. Steps are verifiable learning tasks and hypothetical exercises, not design drawings, method statements, excavation, grouting or confined-space permits, or any project's design documents. Numbers are teaching assumptions or public data; real work must be recalculated and certified by qualified engineers using codes and measured data.","subcategory":"water-rivers","subcategoryTitle":"輸配水、河川與都市防洪","subcategoryTitleEn":"Water conveyance, rivers and urban flood protection","learningTrack":"water","learningSubdiscipline":"water-rivers","learningTags":["water","water-rivers","water"],"architectureFamily":"water-river","architectureNodes":[["高程基準","Elevation datum"],["感測取樣","Sensing and sampling"],["現地記錄","Local logging"],["遙測發布","Telemetry publication"],["品質追溯","Quality traceability"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,4]],"diagram":{"type":"water-river","labels":["高程基準","感測取樣","現地記錄","遙測發布","品質追溯"],"labelsEn":["Elevation datum","Sensing and sampling","Local logging","Telemetry publication","Quality traceability"],"original":true,"notToScale":true},"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"敏感度固定率定係數a=20 m^1.4/s與指數b=1.6，原水位h=2.0 m、零流量參數h0=0.5 m，流量為38.26 m³/s。若水位有正偏差0.10 m而其他參數不變，有效水頭由1.5增至1.6 m，推估流量變成42.43 m³/s，增加約10.88%。這不是把水位增加5%就讓流量增加5%，因率定依有效水頭的非線性冪次變化。實際站點還可能有回水、控制改變及率定參數不確定度；本例只隔離水位偏差，不能據此宣稱流量總誤差或設置警戒值。","textEn":"Hold rating coefficient a=20 m^1.4/s and exponent b=1.6 fixed, with h=2.0 m and zero-flow parameter h0=0.5 m. The baseline estimate is 38.26 m³/s. A positive stage bias of 0.10 m raises effective head from 1.5 to 1.6 m and gives 42.43 m³/s, approximately 10.88% higher. A five-percent increase in the displayed stage therefore does not produce a five-percent discharge change, because the relation is nonlinear in effective head. Real stations additionally face backwater, control changes and uncertain rating parameters. This isolates stage bias only and establishes neither total discharge error nor a warning setting. Datum checks and independent discharge measurements remain separate evidence needed to evaluate the resulting record.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"depth":5,"languageCoverage":["zh-TW","en"],"simulationOnly":true,"educationEdition":15,"enrichmentVersion":15,"stages":[{"id":"b269-v15-s1","title":"水文條件、邊界與工程系統","titleEn":"Hydrology, boundaries and engineering system","description":"本階段聚焦「測站基準與水面高程機理與驗證」與「壓力式量測與氣壓補償機理與驗證」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Gage datum and water elevation mechanism and verification\" and \"Pressure sensing and barometric compensation mechanism and verification\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b269-v15-01","title":"測站基準與水面高程機理與驗證：機制與系統路徑","titleEn":"Gage datum and water elevation mechanism and verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":[],"objective":"說明「測站基準與水面高程」如何影響河川水位自動遙測的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Gage datum and water elevation” governs forces, deformation, flow or signals in “Automatic river-level telemetry”, and map the relevant inputs, transfer paths and boundaries.","instruction":"水位計讀值通常相對測站自訂零點，不等於海拔或工程共用高程。基準點沉陷、支架位移與換儀器可能使整段資料產生偏移，即使曲線仍然平滑；跨站或與堤頂比較前必須連接相同垂直基準，並保存基準更動日期，避免把儀器零點變化誤認為河川水位突變。本例基準與讀值已用同一垂直系統及公尺表示；沒有處理不同國家高程系統、橢球高或潮位基準間的轉換。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「測站基準與水面高程」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A gage reading is generally relative to a station datum rather than sea level or a shared project elevation. Benchmark settlement, support movement and instrument replacement can shift an entire record while leaving a smooth curve. Comparing stations or levee crests requires a common vertical datum and documented changes so that instrument offsets are not mistaken for river-level changes. The example uses meters and one vertical system for datum and reading. It does not convert national height systems, ellipsoidal heights or tidal datums. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Gage datum and water elevation” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設算例，以下量值用於簡化機理比較：假設測站零點高程z0=100.00 m、水尺讀值h=2.35 m，水面高程Z=z0+h=102.35 m。","observationEn":"Order-of-magnitude cue: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume gage-datum elevation z0=100.00 m and reading h=2.35 m.","failure":"常見誤解：「所有水位計顯示的公尺數都已是同一海拔基準下的高程。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Every water-level reading in meters already uses the same sea-level datum.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「測站基準與水面高程」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Gage datum and water elevation”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b269-v15-01-k1","title":"測站基準與水面高程機理與驗證","titleEn":"Gage datum and water elevation mechanism and verification","text":"水位計讀值通常相對測站自訂零點，不等於海拔或工程共用高程。基準點沉陷、支架位移與換儀器可能使整段資料產生偏移，即使曲線仍然平滑；跨站或與堤頂比較前必須連接相同垂直基準，並保存基準更動日期，避免把儀器零點變化誤認為河川水位突變。","textEn":"A gage reading is generally relative to a station datum rather than sea level or a shared project elevation. Benchmark settlement, support movement and instrument replacement can shift an entire record while leaving a smooth curve.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：所有水位計顯示的公尺數都已是同一海拔基準下的高程。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Every water-level reading in meters already uses the same sea-level datum. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"關於「測站基準與水面高程機理與驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Gage datum and water elevation mechanism and verification\" is correct?","options":["所有水位計顯示的公尺數都已是同一海拔基準下的高程。","水位計讀值通常相對測站自訂零點，不等於海拔或工程共用高程。","任何壓力感測器輸出除以水重度就一定得到真實河川水深。"],"optionsEn":["Every water-level reading in meters already uses the same sea-level datum.","A gage reading is generally relative to a station datum rather than sea level or a shared project elevation.","Any pressure output divided by water unit weight gives true river depth."],"answer":1,"explanation":"水位計讀值通常相對測站自訂零點，不等於海拔或工程共用高程。 其餘選項是常見誤解。","explanationEn":"A gage reading is generally relative to a station datum rather than sea level or a shared project elevation. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":1},{"id":"b269-v15-02","title":"測站基準與水面高程機理與驗證：定量估算","titleEn":"Gage datum and water elevation mechanism and verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-01"],"objective":"以數值模型估算「測站基準與水面高程」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Gage datum and water elevation” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設算例，以下量值用於簡化機理比較：假設測站零點高程z0=100.00 m、水尺讀值h=2.35 m，水面高程Z=z0+h=102.35 m。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume gage-datum elevation z0=100.00 m and reading h=2.35 m. Water-surface elevation Z=z0+h=102.35 m. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：由獨立穩定基準點檢查水尺及感測器標高，保留水準閉合與前後儀器高度。","observationEn":"How to cross-check: Check staff-gage and sensor elevations from independent stable marks, retaining leveling closure and instrument-height records.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b269-v15-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設算例，以下量值用於簡化機理比較：假設測站零點高程z0=100.00 m、水尺讀值h=2.35 m，水面高程Z=z0+h=102.35 m。","textEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume gage-datum elevation z0=100.00 m and reading h=2.35 m. Water-surface elevation Z=z0+h=102.35 m.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"依「測站基準與水面高程機理與驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Gage datum and water elevation mechanism and verification\", which statement holds?","options":["只要圖表每秒重畫，就代表河川每秒都有一筆新量測。","裝好水位計後，任何洪水流量都能無誤差地自動換算。","原創教學假設算例，以下量值用於簡化機理比較：假設測站零點高程z0=100.00 m、水尺讀值h=2.35 m，水面高程Z=z0+h=102.35 m。"],"optionsEn":["A graph refreshed every second means the river has a new measurement every second.","Once a stage sensor is installed, every flood discharge converts automatically without error.","Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume gage-datum elevation z0=100.00 m and reading h=2.35 m."],"answer":2,"explanation":"原創教學假設算例，以下量值用於簡化機理比較：假設測站零點高程z0=100.00 m、水尺讀值h=2.35 m，水面高程Z=z0+h=102.35 m。 重算時請保留單位。","explanationEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume gage-datum elevation z0=100.00 m and reading h=2.35 m. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":2},{"id":"b269-v15-03","title":"測站基準與水面高程機理與驗證：試驗與驗證","titleEn":"Gage datum and water elevation mechanism and verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「測站基準與水面高程」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Gage datum and water elevation” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"由獨立穩定基準點檢查水尺及感測器標高，保留水準閉合與前後儀器高度。對任何零點改正加上生效日期和版本，並用同時人工讀值確認自動資料沒有未標記跳變。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check staff-gage and sensor elevations from independent stable marks, retaining leveling closure and instrument-height records. Date and version every datum correction, and compare simultaneous manual observations to ensure that automated data contain no unmarked discontinuity after installation or adjustment. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：為兩站建立零點、讀值和水面高程表，讓一站零點改變但實際水面不變。說明資料庫應如何保留原值、改正值及版本，以免形成假洪峰。","observationEn":"Site practice: Build datum, reading and elevation tables for two stations, changing one datum without changing the physical surface. Explain how original values, corrections and versions should be retained to prevent an artificial flood peak.","failure":"注意干擾：把局部水尺數字直接和海拔堤頂比較會產生錯誤餘高，支架沉陷又可能讓整季記錄偏移；若改正覆蓋原資料，事後便無法追溯當時顯示的警戒情境。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Comparing a local gage number directly with a levee elevation gives false freeboard, and support settlement can bias a season of data. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b269-v15-03-k1","title":"驗證方法","titleEn":"Verification method","text":"由獨立穩定基準點檢查水尺及感測器標高，保留水準閉合與前後儀器高度。對任何零點改正加上生效日期和版本，並用同時人工讀值確認自動資料沒有未標記跳變。","textEn":"Check staff-gage and sensor elevations from independent stable marks, retaining leveling closure and instrument-height records. Date and version every datum correction, and compare simultaneous manual observations to ensure that automated data contain no unmarked discontinuity after installation or adjustment.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-03-k2","title":"現場實務","titleEn":"Site practice","text":"為兩站建立零點、讀值和水面高程表，讓一站零點改變但實際水面不變。說明資料庫應如何保留原值、改正值及版本，以免形成假洪峰。","textEn":"Build datum, reading and elevation tables for two stations, changing one datum without changing the physical surface. Explain how original values, corrections and versions should be retained to prevent an artificial flood peak.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"要驗證「測站基準與水面高程機理與驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Gage datum and water elevation mechanism and verification\"?","options":["由獨立穩定基準點檢查水尺及感測器標高，保留水準閉合與前後儀器高度。","量測時不必記錄溫度、水頭、水位歷程與施工荷重，因為它們不會影響結果。","感測器顯示到毫米，就代表水面絕對高程也準確到毫米。"],"optionsEn":["Check staff-gage and sensor elevations from independent stable marks, retaining leveling closure and instrument-height records.","Temperature, water head, water-level history and construction loads need not be recorded because they cannot affect the result.","Millimeter display resolution means absolute water elevation is accurate to a millimeter."],"answer":0,"explanation":"由獨立穩定基準點檢查水尺及感測器標高，保留水準閉合與前後儀器高度。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check staff-gage and sensor elevations from independent stable marks, retaining leveling closure and instrument-height records. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":3},{"id":"b269-v15-04","title":"測站基準與水面高程機理與驗證：失效診斷","titleEn":"Gage datum and water elevation mechanism and verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-03"],"objective":"從症狀倒推「測站基準與水面高程」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Gage datum and water elevation” and propose discriminating checks, corrective actions and prevention.","instruction":"把局部水尺數字直接和海拔堤頂比較會產生錯誤餘高，支架沉陷又可能讓整季記錄偏移；若改正覆蓋原資料，事後便無法追溯當時顯示的警戒情境。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Comparing a local gage number directly with a levee elevation gives false freeboard, and support settlement can bias a season of data. Overwriting originals with corrections prevents reconstruction of the warning information displayed at the time. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：本例基準與讀值已用同一垂直系統及公尺表示；沒有處理不同國家高程系統、橢球高或潮位基準間的轉換。","observationEn":"Link to the mechanism: It does not convert national height systems, ellipsoidal heights or tidal datums.","failure":"誤判風險：若相信「所有水位計顯示的公尺數都已是同一海拔基準下的高程。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Every water-level reading in meters already uses the same sea-level datum.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b269-v15-04-k1","title":"失效模式","titleEn":"Failure mode","text":"把局部水尺數字直接和海拔堤頂比較會產生錯誤餘高，支架沉陷又可能讓整季記錄偏移；若改正覆蓋原資料，事後便無法追溯當時顯示的警戒情境。","textEn":"Comparing a local gage number directly with a levee elevation gives false freeboard, and support settlement can bias a season of data. Overwriting originals with corrections prevents reconstruction of the warning information displayed at the time.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"在「測站基準與水面高程機理與驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Gage datum and water elevation mechanism and verification\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","把局部水尺數字直接和海拔堤頂比較會產生錯誤餘高，支架沉陷又可能讓整季記錄偏移；若改正覆蓋原資料，事後便無法追溯當時顯示的警戒情境。","任何壓力感測器輸出除以水重度就一定得到真實河川水深。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Comparing a local gage number directly with a levee elevation gives false freeboard, and support settlement can bias a season of data.","Any pressure output divided by water unit weight gives true river depth."],"answer":1,"explanation":"把局部水尺數字直接和海拔堤頂比較會產生錯誤餘高，支架沉陷又可能讓整季記錄偏移；若改正覆蓋原資料，事後便無法追溯當時顯示的警戒情境。 需以量測區分可能原因。","explanationEn":"Comparing a local gage number directly with a levee elevation gives false freeboard, and support settlement can bias a season of data. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":4},{"id":"b269-v15-05","title":"壓力式量測與氣壓補償機理與驗證：機制與系統路徑","titleEn":"Pressure sensing and barometric compensation mechanism and verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-04"],"objective":"說明「壓力式量測與氣壓補償」如何影響河川水位自動遙測的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Pressure sensing and barometric compensation” governs forces, deformation, flow or signals in “Automatic river-level telemetry”, and map the relevant inputs, transfer paths and boundaries.","instruction":"浸水式壓力計依水柱壓力換算深度，絕對壓力感測器需扣除同步大氣壓，通氣式則依通氣管維持參考。水密度受溫鹽影響，感測器位置也可能被淤埋或漂移；因此壓力變化不一定全是水位變化，氣壓補償和安裝高程必須與原始壓力一起保存。本例使用已扣氣壓的表壓並假設靜水、淡水定密度；在高速流或堵塞導壓管附近，動壓與延遲需要另行評估。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「壓力式量測與氣壓補償」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A submerged pressure sensor converts water-column pressure to depth. Absolute sensors require synchronized atmospheric subtraction, while vented sensors rely on a reference vent. Density varies with temperature and salinity, and the sensor can be buried or displaced. Pressure changes therefore need not all represent stage changes; barometric compensation and installation elevation must accompany the raw pressure record. The example uses gauge pressure after atmospheric subtraction and assumes hydrostatic freshwater of fixed density. Dynamic pressure and lag require separate assessment near fast flow or blocked pressure tubing. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Pressure sensing and barometric compensation” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設算例，以下量值用於簡化機理比較：假設表壓p=19620 Pa、ρ=1000 kg/m³、g=9.81 m/s²，水柱h=p/(ρg)=2.00 m。","observationEn":"Order-of-magnitude cue: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume gauge pressure p=19620 Pa, density ρ=1000 kg/m³ and g=9.81 m/s².","failure":"常見誤解：「任何壓力感測器輸出除以水重度就一定得到真實河川水深。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Any pressure output divided by water unit weight gives true river depth.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「壓力式量測與氣壓補償」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Pressure sensing and barometric compensation”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b269-v15-05-k1","title":"壓力式量測與氣壓補償機理與驗證","titleEn":"Pressure sensing and barometric compensation mechanism and verification","text":"浸水式壓力計依水柱壓力換算深度，絕對壓力感測器需扣除同步大氣壓，通氣式則依通氣管維持參考。水密度受溫鹽影響，感測器位置也可能被淤埋或漂移；因此壓力變化不一定全是水位變化，氣壓補償和安裝高程必須與原始壓力一起保存。","textEn":"A submerged pressure sensor converts water-column pressure to depth. Absolute sensors require synchronized atmospheric subtraction, while vented sensors rely on a reference vent.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：任何壓力感測器輸出除以水重度就一定得到真實河川水深。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Any pressure output divided by water unit weight gives true river depth. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"關於「壓力式量測與氣壓補償機理與驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Pressure sensing and barometric compensation mechanism and verification\" is correct?","options":["任何壓力感測器輸出除以水重度就一定得到真實河川水深。","雷達不接觸水，所以不需要高程測量或現地水尺交叉驗證。","浸水式壓力計依水柱壓力換算深度，絕對壓力感測器需扣除同步大氣壓，通氣式則依通氣管維持參考。"],"optionsEn":["Any pressure output divided by water unit weight gives true river depth.","Noncontact radar needs neither elevation surveying nor field staff-gage checks.","A submerged pressure sensor converts water-column pressure to depth."],"answer":2,"explanation":"浸水式壓力計依水柱壓力換算深度，絕對壓力感測器需扣除同步大氣壓，通氣式則依通氣管維持參考。 其餘選項是常見誤解。","explanationEn":"A submerged pressure sensor converts water-column pressure to depth. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":5},{"id":"b269-v15-06","title":"壓力式量測與氣壓補償機理與驗證：定量估算","titleEn":"Pressure sensing and barometric compensation mechanism and verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-05"],"objective":"以數值模型估算「壓力式量測與氣壓補償」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Pressure sensing and barometric compensation” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設算例，以下量值用於簡化機理比較：假設表壓p=19620 Pa、ρ=1000 kg/m³、g=9.81 m/s²，水柱h=p/(ρg)=2.00 m。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume gauge pressure p=19620 Pa, density ρ=1000 kg/m³ and g=9.81 m/s². Water-column height h=p/(ρg)=2.00 m. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：同步記錄水壓與氣壓，核對壓力種類、單位與感測器標高，並以人工水尺交叉比較。","observationEn":"How to cross-check: Record water and atmospheric pressure synchronously, checking pressure type, units and sensor elevation against a manual staff gage.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b269-v15-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設算例，以下量值用於簡化機理比較：假設表壓p=19620 Pa、ρ=1000 kg/m³、g=9.81 m/s²，水柱h=p/(ρg)=2.00 m。","textEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume gauge pressure p=19620 Pa, density ρ=1000 kg/m³ and g=9.81 m/s². Water-column height h=p/(ρg)=2.00 m.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"依「壓力式量測與氣壓補償機理與驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Pressure sensing and barometric compensation mechanism and verification\", which statement holds?","options":["原創教學假設算例，以下量值用於簡化機理比較：假設表壓p=19620 Pa、ρ=1000 kg/m³、g=9.81 m/s²，水柱h=p/(ρg)=2.00 m。","封包剛收到就一定代表此刻水位，無需再看量測時間。","取樣越密，任何相鄰兩點差分得到的水位速率就一定越可靠。"],"optionsEn":["Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume gauge pressure p=19620 Pa, density ρ=1000 kg/m³ and g=9.81 m/s².","A newly received packet necessarily represents current stage without checking observation time.","Denser sampling always makes a two-point stage derivative more reliable."],"answer":0,"explanation":"原創教學假設算例，以下量值用於簡化機理比較：假設表壓p=19620 Pa、ρ=1000 kg/m³、g=9.81 m/s²，水柱h=p/(ρg)=2.00 m。 重算時請保留單位。","explanationEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume gauge pressure p=19620 Pa, density ρ=1000 kg/m³ and g=9.81 m/s². Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":6},{"id":"b269-v15-07","title":"壓力式量測與氣壓補償機理與驗證：試驗與驗證","titleEn":"Pressure sensing and barometric compensation mechanism and verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「壓力式量測與氣壓補償」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Pressure sensing and barometric compensation” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"同步記錄水壓與氣壓，核對壓力種類、單位與感測器標高，並以人工水尺交叉比較。檢查通氣管結露、導壓管堵塞與漂移，避免用軟體校正常數掩蓋實際安裝故障。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Record water and atmospheric pressure synchronously, checking pressure type, units and sensor elevation against a manual staff gage. Inspect vent condensation, pressure-line blockage and displacement so that software correction constants do not conceal physical installation faults or delayed response. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較相同水位下兩種大氣壓的絕對壓力讀值，完成扣除後確認水深不變。再加入氣壓資料延遲情境，說明時間同步和精確感測同樣必要。","observationEn":"Site practice: Compare absolute readings at two atmospheric pressures with unchanged water level and confirm invariant depth after subtraction. Then introduce delayed barometric data and explain why synchronization matters alongside sensor precision.","failure":"注意干擾：將絕對壓力直接換成水深會把大氣壓算入水柱，通氣管受潮則可能形成緩慢偏差；淤埋造成的遲滯也可能讓洪峰看起來較低且較晚。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Converting absolute pressure directly includes atmospheric pressure as water depth. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b269-v15-07-k1","title":"驗證方法","titleEn":"Verification method","text":"同步記錄水壓與氣壓，核對壓力種類、單位與感測器標高，並以人工水尺交叉比較。檢查通氣管結露、導壓管堵塞與漂移，避免用軟體校正常數掩蓋實際安裝故障。","textEn":"Record water and atmospheric pressure synchronously, checking pressure type, units and sensor elevation against a manual staff gage. Inspect vent condensation, pressure-line blockage and displacement so that software correction constants do not conceal physical installation faults or delayed response.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-07-k2","title":"現場實務","titleEn":"Site practice","text":"比較相同水位下兩種大氣壓的絕對壓力讀值，完成扣除後確認水深不變。再加入氣壓資料延遲情境，說明時間同步和精確感測同樣必要。","textEn":"Compare absolute readings at two atmospheric pressures with unchanged water level and confirm invariant depth after subtraction. Then introduce delayed barometric data and explain why synchronization matters alongside sensor precision.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"要驗證「壓力式量測與氣壓補償機理與驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Pressure sensing and barometric compensation mechanism and verification\"?","options":["沿用另一處水工設施或流域的量測結果，就可視為本工程已完成驗證。","同步記錄水壓與氣壓，核對壓力種類、單位與感測器標高，並以人工水尺交叉比較。","電池安培小時越大就可直接比較續航，不需要知道電壓或負載。"],"optionsEn":["Reusing results from another hydraulic structure or catchment counts as verifying this structure.","Record water and atmospheric pressure synchronously, checking pressure type, units and sensor elevation against a manual staff gage.","Battery ampere-hours alone compare endurance without voltage or load information."],"answer":1,"explanation":"同步記錄水壓與氣壓，核對壓力種類、單位與感測器標高，並以人工水尺交叉比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Record water and atmospheric pressure synchronously, checking pressure type, units and sensor elevation against a manual staff gage. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":7},{"id":"b269-v15-08","title":"壓力式量測與氣壓補償機理與驗證：失效診斷","titleEn":"Pressure sensing and barometric compensation mechanism and verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-07"],"objective":"從症狀倒推「壓力式量測與氣壓補償」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Pressure sensing and barometric compensation” and propose discriminating checks, corrective actions and prevention.","instruction":"將絕對壓力直接換成水深會把大氣壓算入水柱，通氣管受潮則可能形成緩慢偏差；淤埋造成的遲滯也可能讓洪峰看起來較低且較晚。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Converting absolute pressure directly includes atmospheric pressure as water depth. A wet vent can produce gradual bias, while sediment burial may delay response and make a flood crest appear lower and later. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：本例使用已扣氣壓的表壓並假設靜水、淡水定密度；在高速流或堵塞導壓管附近，動壓與延遲需要另行評估。","observationEn":"Link to the mechanism: Dynamic pressure and lag require separate assessment near fast flow or blocked pressure tubing.","failure":"誤判風險：若相信「任何壓力感測器輸出除以水重度就一定得到真實河川水深。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Any pressure output divided by water unit weight gives true river depth.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b269-v15-08-k1","title":"失效模式","titleEn":"Failure mode","text":"將絕對壓力直接換成水深會把大氣壓算入水柱，通氣管受潮則可能形成緩慢偏差；淤埋造成的遲滯也可能讓洪峰看起來較低且較晚。","textEn":"Converting absolute pressure directly includes atmospheric pressure as water depth. A wet vent can produce gradual bias, while sediment burial may delay response and make a flood crest appear lower and later.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"在「壓力式量測與氣壓補償機理與驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Pressure sensing and barometric compensation mechanism and verification\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","雷達不接觸水，所以不需要高程測量或現地水尺交叉驗證。","將絕對壓力直接換成水深會把大氣壓算入水柱，通氣管受潮則可能形成緩慢偏差；淤埋造成的遲滯也可能讓洪峰看起來較低且較晚。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Noncontact radar needs neither elevation surveying nor field staff-gage checks.","Converting absolute pressure directly includes atmospheric pressure as water depth."],"answer":2,"explanation":"將絕對壓力直接換成水深會把大氣壓算入水柱，通氣管受潮則可能形成緩慢偏差；淤埋造成的遲滯也可能讓洪峰看起來較低且較晚。 需以量測區分可能原因。","explanationEn":"Converting absolute pressure directly includes atmospheric pressure as water depth. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":8}],"order":1},{"id":"b269-v15-s2","title":"水力機制、材料與定量模型","titleEn":"Hydraulics, materials and quantitative models","description":"本階段聚焦「雷達距離與安裝幾何機理與驗證」與「取樣間隔與漏失洪峰機理與驗證」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Radar range and installation geometry mechanism and verification\" and \"Sampling interval and missed crests mechanism and verification\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b269-v15-09","title":"雷達距離與安裝幾何機理與驗證：機制與系統路徑","titleEn":"Radar range and installation geometry mechanism and verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-08"],"objective":"說明「雷達距離與安裝幾何」如何影響河川水位自動遙測的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Radar range and installation geometry” governs forces, deformation, flow or signals in “Automatic river-level telemetry”, and map the relevant inputs, transfer paths and boundaries.","instruction":"非接觸雷達由天線到水面的傳播訊號求距離，再與天線高程組合成水面高程。量到的是距離而不是直接水位，斜裝、波浪、橋構件與漂浮物可能改變有效回波；儀器內部常使用調頻等處理，但基礎往返傳播關係仍可用來核對量綱與幾何方向。本例為理想垂直往返飛行時間示意，近似空氣中光速；不是描述特定雷達的電子取樣解析度或實際量測準確度。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「雷達距離與安裝幾何」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Noncontact radar derives antenna-to-surface range from the propagation signal and combines it with antenna elevation. It measures distance rather than stage directly; tilt, waves, bridge members and floating debris can change the effective return. Practical instruments often use frequency-modulated processing, but the basic round-trip relation remains useful for checking dimensions and geometric direction. The example illustrates ideal vertical round-trip travel time using approximate light speed in air. It does not describe a particular radar’s sampling resolution or field accuracy. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Radar range and installation geometry” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設算例，以下量值用於簡化機理比較：假設c=3.0×10⁸ m/s、往返t=40 ns，距離d=ct/2=6.00 m；天線Zs=110 m時水面Z=104 m。","observationEn":"Order-of-magnitude cue: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume c=3.0×10⁸ m/s and round-trip t=40 ns.","failure":"常見誤解：「雷達不接觸水，所以不需要高程測量或現地水尺交叉驗證。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Noncontact radar needs neither elevation surveying nor field staff-gage checks.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「雷達距離與安裝幾何」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Radar range and installation geometry”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b269-v15-09-k1","title":"雷達距離與安裝幾何機理與驗證","titleEn":"Radar range and installation geometry mechanism and verification","text":"非接觸雷達由天線到水面的傳播訊號求距離，再與天線高程組合成水面高程。量到的是距離而不是直接水位，斜裝、波浪、橋構件與漂浮物可能改變有效回波；儀器內部常使用調頻等處理，但基礎往返傳播關係仍可用來核對量綱與幾何方向。","textEn":"Noncontact radar derives antenna-to-surface range from the propagation signal and combines it with antenna elevation. It measures distance rather than stage directly; tilt, waves, bridge members and floating debris can change the effective return.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：雷達不接觸水，所以不需要高程測量或現地水尺交叉驗證。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Noncontact radar needs neither elevation surveying nor field staff-gage checks. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"關於「雷達距離與安裝幾何機理與驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Radar range and installation geometry mechanism and verification\" is correct?","options":["非接觸雷達由天線到水面的傳播訊號求距離，再與天線高程組合成水面高程。","雷達不接觸水，所以不需要高程測量或現地水尺交叉驗證。","只要圖表每秒重畫，就代表河川每秒都有一筆新量測。"],"optionsEn":["Noncontact radar derives antenna-to-surface range from the propagation signal and combines it with antenna elevation.","Noncontact radar needs neither elevation surveying nor field staff-gage checks.","A graph refreshed every second means the river has a new measurement every second."],"answer":0,"explanation":"非接觸雷達由天線到水面的傳播訊號求距離，再與天線高程組合成水面高程。 其餘選項是常見誤解。","explanationEn":"Noncontact radar derives antenna-to-surface range from the propagation signal and combines it with antenna elevation. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":9},{"id":"b269-v15-10","title":"雷達距離與安裝幾何機理與驗證：定量估算","titleEn":"Radar range and installation geometry mechanism and verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-09"],"objective":"以數值模型估算「雷達距離與安裝幾何」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Radar range and installation geometry” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設算例，以下量值用於簡化機理比較：假設c=3.0×10⁸ m/s、往返t=40 ns，距離d=ct/2=6.00 m；天線Zs=110 m時水面Z=104 m。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume c=3.0×10⁸ m/s and round-trip t=40 ns. Range d=ct/2=6.00 m; antenna elevation Zs=110 m gives water elevation Z=104 m. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：量測天線標高與傾角並檢查波束覆蓋，將回波品質和水尺讀值同步保存。","observationEn":"How to cross-check: Survey antenna elevation and tilt, inspect beam coverage and retain echo-quality indicators with simultaneous staff-gage readings.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b269-v15-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設算例，以下量值用於簡化機理比較：假設c=3.0×10⁸ m/s、往返t=40 ns，距離d=ct/2=6.00 m；天線Zs=110 m時水面Z=104 m。","textEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume c=3.0×10⁸ m/s and round-trip t=40 ns. Range d=ct/2=6.00 m; antenna elevation Zs=110 m gives water elevation Z=104 m.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"依「雷達距離與安裝幾何機理與驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Radar range and installation geometry mechanism and verification\", which statement holds?","options":["裝好水位計後，任何洪水流量都能無誤差地自動換算。","原創教學假設算例，以下量值用於簡化機理比較：假設c=3.0×10⁸ m/s、往返t=40 ns，距離d=ct/2=6.00 m。","感測器顯示到毫米，就代表水面絕對高程也準確到毫米。"],"optionsEn":["Once a stage sensor is installed, every flood discharge converts automatically without error.","Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume c=3.0×10⁸ m/s and round-trip t=40 ns.","Millimeter display resolution means absolute water elevation is accurate to a millimeter."],"answer":1,"explanation":"原創教學假設算例，以下量值用於簡化機理比較：假設c=3.0×10⁸ m/s、往返t=40 ns，距離d=ct/2=6.00 m；天線Zs=110 m時水面Z=104 m。 重算時請保留單位。","explanationEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume c=3.0×10⁸ m/s and round-trip t=40 ns. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":10},{"id":"b269-v15-11","title":"雷達距離與安裝幾何機理與驗證：試驗與驗證","titleEn":"Radar range and installation geometry mechanism and verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「雷達距離與安裝幾何」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Radar range and installation geometry” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"量測天線標高與傾角並檢查波束覆蓋，將回波品質和水尺讀值同步保存。針對橋面反射、漂浮物及暴雨測試異常旗標，確認失去有效水面回波時不會輸出看似正常的舊值。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Survey antenna elevation and tilt, inspect beam coverage and retain echo-quality indicators with simultaneous staff-gage readings. Test anomaly flags for bridge reflections, floating objects and intense rain, ensuring that lost water-surface returns do not silently appear as normal stale measurements. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：畫出天線、橋構件及水面三個回波路徑，指出哪條距離可用於水面高程。改變天線標高並保持水面不變，說明資料系統必須同步更新哪些參數。","observationEn":"Site practice: Draw antenna, bridge-member and water-surface return paths, identifying the range usable for elevation. Change antenna height without moving the water and explain which data-system parameters must be updated together.","failure":"注意干擾：漏除往返因子二會把距離加倍，天線支架位移則使所有高程產生偏移；挑錯回波可能讀到橋梁或漂流物，曲線平滑也不能保證目標正確。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Omitting the round-trip factor doubles range, and support movement shifts all elevations. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b269-v15-11-k1","title":"驗證方法","titleEn":"Verification method","text":"量測天線標高與傾角並檢查波束覆蓋，將回波品質和水尺讀值同步保存。針對橋面反射、漂浮物及暴雨測試異常旗標，確認失去有效水面回波時不會輸出看似正常的舊值。","textEn":"Survey antenna elevation and tilt, inspect beam coverage and retain echo-quality indicators with simultaneous staff-gage readings. Test anomaly flags for bridge reflections, floating objects and intense rain, ensuring that lost water-surface returns do not silently appear as normal stale measurements.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-11-k2","title":"現場實務","titleEn":"Site practice","text":"畫出天線、橋構件及水面三個回波路徑，指出哪條距離可用於水面高程。改變天線標高並保持水面不變，說明資料系統必須同步更新哪些參數。","textEn":"Draw antenna, bridge-member and water-surface return paths, identifying the range usable for elevation. Change antenna height without moving the water and explain which data-system parameters must be updated together.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"要驗證「雷達距離與安裝幾何機理與驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Radar range and installation geometry mechanism and verification\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","只要現場裝兩支感測器，就一定可以把全部失效機率相乘。","量測天線標高與傾角並檢查波束覆蓋，將回波品質和水尺讀值同步保存。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Installing two field sensors always permits multiplication of all failure probabilities.","Survey antenna elevation and tilt, inspect beam coverage and retain echo-quality indicators with simultaneous staff-gage readings."],"answer":2,"explanation":"量測天線標高與傾角並檢查波束覆蓋，將回波品質和水尺讀值同步保存。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Survey antenna elevation and tilt, inspect beam coverage and retain echo-quality indicators with simultaneous staff-gage readings. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":11},{"id":"b269-v15-12","title":"雷達距離與安裝幾何機理與驗證：失效診斷","titleEn":"Radar range and installation geometry mechanism and verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-11"],"objective":"從症狀倒推「雷達距離與安裝幾何」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Radar range and installation geometry” and propose discriminating checks, corrective actions and prevention.","instruction":"漏除往返因子二會把距離加倍，天線支架位移則使所有高程產生偏移；挑錯回波可能讀到橋梁或漂流物，曲線平滑也不能保證目標正確。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Omitting the round-trip factor doubles range, and support movement shifts all elevations. Selecting the wrong return may track a bridge or floating debris; a smooth time series does not guarantee the correct target. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：本例為理想垂直往返飛行時間示意，近似空氣中光速；不是描述特定雷達的電子取樣解析度或實際量測準確度。","observationEn":"Link to the mechanism: It does not describe a particular radar’s sampling resolution or field accuracy.","failure":"誤判風險：若相信「雷達不接觸水，所以不需要高程測量或現地水尺交叉驗證。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Noncontact radar needs neither elevation surveying nor field staff-gage checks.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b269-v15-12-k1","title":"失效模式","titleEn":"Failure mode","text":"漏除往返因子二會把距離加倍，天線支架位移則使所有高程產生偏移；挑錯回波可能讀到橋梁或漂流物，曲線平滑也不能保證目標正確。","textEn":"Omitting the round-trip factor doubles range, and support movement shifts all elevations. Selecting the wrong return may track a bridge or floating debris; a smooth time series does not guarantee the correct target.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"在「雷達距離與安裝幾何機理與驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Radar range and installation geometry mechanism and verification\" shows distress, which diagnosis is most reasonable?","options":["漏除往返因子二會把距離加倍，天線支架位移則使所有高程產生偏移；挑錯回波可能讀到橋梁或漂流物，曲線平滑也不能保證目標正確。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","只要圖表每秒重畫，就代表河川每秒都有一筆新量測。"],"optionsEn":["Omitting the round-trip factor doubles range, and support movement shifts all elevations.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","A graph refreshed every second means the river has a new measurement every second."],"answer":0,"explanation":"漏除往返因子二會把距離加倍，天線支架位移則使所有高程產生偏移；挑錯回波可能讀到橋梁或漂流物，曲線平滑也不能保證目標正確。 需以量測區分可能原因。","explanationEn":"Omitting the round-trip factor doubles range, and support movement shifts all elevations. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":12},{"id":"b269-v15-13","title":"取樣間隔與漏失洪峰機理與驗證：機制與系統路徑","titleEn":"Sampling interval and missed crests mechanism and verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-12"],"objective":"說明「取樣間隔與漏失洪峰」如何影響河川水位自動遙測的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Sampling interval and missed crests” governs forces, deformation, flow or signals in “Automatic river-level telemetry”, and map the relevant inputs, transfer paths and boundaries.","instruction":"離散水位資料只能觀察取樣時刻，洪峰若發生在兩筆之間就可能被低估。提高取樣頻率可縮小這類誤差，但儲存、傳輸頻率與畫面更新不一定相同；平均濾波又可能壓低短時尖峰，因此應保存原始取樣時間，並區分缺測與真正平穩水位。下式假設內部洪峰附近水位變化速率有已知上限且兩側取樣完整；只界定時間離散誤差，未含儀器誤差或資料中斷。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「取樣間隔與漏失洪峰」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Discrete records observe stage only at sample times, so a crest between samples can be underestimated. Faster sampling reduces this error, but storage, transmission and display frequencies need not match. Averaging can additionally suppress short peaks, making original timestamps and a clear distinction between missing data and genuinely stable stage essential. The bound assumes a known maximum rate around an interior crest and complete samples on both sides. It concerns temporal discretization only, excluding sensor error and missing records. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Sampling interval and missed crests” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設算例，以下量值用於簡化機理比較：假設|dh/dt|≤r=0.004 m/s、等距取樣Δt=60 s，洪峰到最近取樣最多30 s，漏峰界限rΔt/2=0.12 m。","observationEn":"Order-of-magnitude cue: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume |dh/dt|≤r=0.004 m/s and sample interval Δt=60 s.","failure":"常見誤解：「只要圖表每秒重畫，就代表河川每秒都有一筆新量測。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A graph refreshed every second means the river has a new measurement every second.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「取樣間隔與漏失洪峰」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Sampling interval and missed crests”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b269-v15-13-k1","title":"取樣間隔與漏失洪峰機理與驗證","titleEn":"Sampling interval and missed crests mechanism and verification","text":"離散水位資料只能觀察取樣時刻，洪峰若發生在兩筆之間就可能被低估。提高取樣頻率可縮小這類誤差，但儲存、傳輸頻率與畫面更新不一定相同；平均濾波又可能壓低短時尖峰，因此應保存原始取樣時間，並區分缺測與真正平穩水位。","textEn":"Discrete records observe stage only at sample times, so a crest between samples can be underestimated. Faster sampling reduces this error, but storage, transmission and display frequencies need not match.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要圖表每秒重畫，就代表河川每秒都有一筆新量測。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A graph refreshed every second means the river has a new measurement every second. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"關於「取樣間隔與漏失洪峰機理與驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Sampling interval and missed crests mechanism and verification\" is correct?","options":["只要圖表每秒重畫，就代表河川每秒都有一筆新量測。","離散水位資料只能觀察取樣時刻，洪峰若發生在兩筆之間就可能被低估。","封包剛收到就一定代表此刻水位，無需再看量測時間。"],"optionsEn":["A graph refreshed every second means the river has a new measurement every second.","Discrete records observe stage only at sample times, so a crest between samples can be underestimated.","A newly received packet necessarily represents current stage without checking observation time."],"answer":1,"explanation":"離散水位資料只能觀察取樣時刻，洪峰若發生在兩筆之間就可能被低估。 其餘選項是常見誤解。","explanationEn":"Discrete records observe stage only at sample times, so a crest between samples can be underestimated. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":13},{"id":"b269-v15-14","title":"取樣間隔與漏失洪峰機理與驗證：定量估算","titleEn":"Sampling interval and missed crests mechanism and verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-13"],"objective":"以數值模型估算「取樣間隔與漏失洪峰」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Sampling interval and missed crests” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設算例，以下量值用於簡化機理比較：假設|dh/dt|≤r=0.004 m/s、等距取樣Δt=60 s，洪峰到最近取樣最多30 s，漏峰界限rΔt/2=0.12 m。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume |dh/dt|≤r=0.004 m/s and sample interval Δt=60 s. The nearest sample is at most 30 s away, giving missed-crest bound rΔt/2=0.12 m. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：從原始時間戳檢查實際取樣間距及遺漏，將平均後曲線與高頻原資料比較。","observationEn":"How to cross-check: Check actual intervals and omissions from original timestamps, comparing averaged curves with high-frequency records.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b269-v15-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設算例，以下量值用於簡化機理比較：假設|dh/dt|≤r=0.004 m/s、等距取樣Δt=60 s，洪峰到最近取樣最多30 s，漏峰界限rΔt/2=0.12 m。","textEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume |dh/dt|≤r=0.004 m/s and sample interval Δt=60 s. The nearest sample is at most 30 s away, giving missed-crest bound rΔt/2=0.12 m.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"依「取樣間隔與漏失洪峰機理與驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Sampling interval and missed crests mechanism and verification\", which statement holds?","options":["取樣越密，任何相鄰兩點差分得到的水位速率就一定越可靠。","電池安培小時越大就可直接比較續航，不需要知道電壓或負載。","原創教學假設算例，以下量值用於簡化機理比較：假設|dh/dt|≤r=0.004 m/s、等距取樣Δt=60 s，洪峰到最近取樣最多30 s，漏峰界限rΔt/2=0.12 m。"],"optionsEn":["Denser sampling always makes a two-point stage derivative more reliable.","Battery ampere-hours alone compare endurance without voltage or load information.","Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume |dh/dt|≤r=0.004 m/s and sample interval Δt=60 s."],"answer":2,"explanation":"原創教學假設算例，以下量值用於簡化機理比較：假設|dh/dt|≤r=0.004 m/s、等距取樣Δt=60 s，洪峰到最近取樣最多30 s，漏峰界限rΔt/2=0.12 m。 重算時請保留單位。","explanationEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume |dh/dt|≤r=0.004 m/s and sample interval Δt=60 s. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":14},{"id":"b269-v15-15","title":"取樣間隔與漏失洪峰機理與驗證：試驗與驗證","titleEn":"Sampling interval and missed crests mechanism and verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「取樣間隔與漏失洪峰」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Sampling interval and missed crests” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"從原始時間戳檢查實際取樣間距及遺漏，將平均後曲線與高頻原資料比較。以獨立事件驗證速率上限的合理性；若有缺筆或未觀測尖峰，需撤回此完整取樣誤差界限。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check actual intervals and omissions from original timestamps, comparing averaged curves with high-frequency records. Assess the assumed rate bound against independent events; if samples are missing or sharper behavior is unobserved, withdraw this complete-sampling error bound instead of treating it as guaranteed. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：建立一個落在兩取樣點中間的三角洪峰，分別以六十秒和三十秒取樣比較峰值。將顯示更新頻率保持相同，說明它為何不會補回漏掉的觀測。","observationEn":"Site practice: Create a triangular crest between samples and compare sixty- and thirty-second sampling. Keep display refresh unchanged and explain why faster redraws do not recover observations that were never collected.","failure":"注意干擾：把傳輸每小時一次誤當成現地每分鐘取樣會低估資訊延遲，平均值也可能掩蓋警戒尖峰；無資料時延用最後值會產生看似平穩的假象。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Confusing hourly transmission with minute-by-minute local sampling understates information delay, and averaging can conceal a warning crest. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b269-v15-15-k1","title":"驗證方法","titleEn":"Verification method","text":"從原始時間戳檢查實際取樣間距及遺漏，將平均後曲線與高頻原資料比較。以獨立事件驗證速率上限的合理性；若有缺筆或未觀測尖峰，需撤回此完整取樣誤差界限。","textEn":"Check actual intervals and omissions from original timestamps, comparing averaged curves with high-frequency records. Assess the assumed rate bound against independent events; if samples are missing or sharper behavior is unobserved, withdraw this complete-sampling error bound instead of treating it as guaranteed.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-15-k2","title":"現場實務","titleEn":"Site practice","text":"建立一個落在兩取樣點中間的三角洪峰，分別以六十秒和三十秒取樣比較峰值。將顯示更新頻率保持相同，說明它為何不會補回漏掉的觀測。","textEn":"Create a triangular crest between samples and compare sixty- and thirty-second sampling. Keep display refresh unchanged and explain why faster redraws do not recover observations that were never collected.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"要驗證「取樣間隔與漏失洪峰機理與驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Sampling interval and missed crests mechanism and verification\"?","options":["從原始時間戳檢查實際取樣間距及遺漏，將平均後曲線與高頻原資料比較。","不確定度太難估計，報告中只寫最佳值即可。","所有水位計顯示的公尺數都已是同一海拔基準下的高程。"],"optionsEn":["Check actual intervals and omissions from original timestamps, comparing averaged curves with high-frequency records.","Uncertainty is too hard to estimate, so the report may state only the best value.","Every water-level reading in meters already uses the same sea-level datum."],"answer":0,"explanation":"從原始時間戳檢查實際取樣間距及遺漏，將平均後曲線與高頻原資料比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check actual intervals and omissions from original timestamps, comparing averaged curves with high-frequency records. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":15},{"id":"b269-v15-16","title":"取樣間隔與漏失洪峰機理與驗證：失效診斷","titleEn":"Sampling interval and missed crests mechanism and verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-15"],"objective":"從症狀倒推「取樣間隔與漏失洪峰」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Sampling interval and missed crests” and propose discriminating checks, corrective actions and prevention.","instruction":"把傳輸每小時一次誤當成現地每分鐘取樣會低估資訊延遲，平均值也可能掩蓋警戒尖峰；無資料時延用最後值會產生看似平穩的假象。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Confusing hourly transmission with minute-by-minute local sampling understates information delay, and averaging can conceal a warning crest. Repeating the last value during an outage creates the false appearance of stable water level. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：下式假設內部洪峰附近水位變化速率有已知上限且兩側取樣完整；只界定時間離散誤差，未含儀器誤差或資料中斷。","observationEn":"Link to the mechanism: It concerns temporal discretization only, excluding sensor error and missing records.","failure":"誤判風險：若相信「只要圖表每秒重畫，就代表河川每秒都有一筆新量測。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A graph refreshed every second means the river has a new measurement every second.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b269-v15-16-k1","title":"失效模式","titleEn":"Failure mode","text":"把傳輸每小時一次誤當成現地每分鐘取樣會低估資訊延遲，平均值也可能掩蓋警戒尖峰；無資料時延用最後值會產生看似平穩的假象。","textEn":"Confusing hourly transmission with minute-by-minute local sampling understates information delay, and averaging can conceal a warning crest. Repeating the last value during an outage creates the false appearance of stable water level.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"在「取樣間隔與漏失洪峰機理與驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Sampling interval and missed crests mechanism and verification\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","把傳輸每小時一次誤當成現地每分鐘取樣會低估資訊延遲，平均值也可能掩蓋警戒尖峰；無資料時延用最後值會產生看似平穩的假象。","封包剛收到就一定代表此刻水位，無需再看量測時間。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Confusing hourly transmission with minute-by-minute local sampling understates information delay, and averaging can conceal a warning crest.","A newly received packet necessarily represents current stage without checking observation time."],"answer":1,"explanation":"把傳輸每小時一次誤當成現地每分鐘取樣會低估資訊延遲，平均值也可能掩蓋警戒尖峰；無資料時延用最後值會產生看似平穩的假象。 需以量測區分可能原因。","explanationEn":"Confusing hourly transmission with minute-by-minute local sampling understates information delay, and averaging can conceal a warning crest. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":16}],"order":2},{"id":"b269-v15-s3","title":"施工方法與施工階段控制","titleEn":"Construction methods and stage control","description":"本階段聚焦「傳輸延遲與資料時效機理與驗證」與「水位流量關係與外推機理與驗證」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Transmission latency and data age mechanism and verification\" and \"Stage-discharge relation and extrapolation mechanism and verification\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b269-v15-17","title":"傳輸延遲與資料時效機理與驗證：機制與系統路徑","titleEn":"Transmission latency and data age mechanism and verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-16"],"objective":"說明「傳輸延遲與資料時效」如何影響河川水位自動遙測的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Transmission latency and data age” governs forces, deformation, flow or signals in “Automatic river-level telemetry”, and map the relevant inputs, transfer paths and boundaries.","instruction":"自動遙測鏈包含感測、記錄、通訊、接收與發布，各段延遲相加才形成使用者看到的資料年齡。接收時間不等於量測時間，補傳舊封包更可能讓新到資料看似最新水位；洪水快速上升時，即使數值本身準確，過時資料仍可能造成錯誤情境判讀。本例在固定上升速率下比較量測時與現在的差異，不是預報模型；真實加速度、回落及通訊中斷會破壞線性外推。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「傳輸延遲與資料時效」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"An automated chain includes sensing, logging, communication, reception and publication; their delays determine the age of displayed information. Receipt time is not observation time, and retransmitted old packets can look deceptively current. During a rapid rise, an accurate but stale reading can still produce a misleading picture of the river. The example compares observation time with the present under a constant rise rate. It is not a forecast model; acceleration, recession and communication outages invalidate simple linear extrapolation. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Transmission latency and data age” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設算例，以下量值用於簡化機理比較：假設水位上升率r=0.003 m/s、總資料延遲L=120 s，線性時效差Δh=rL=0.36 m。","observationEn":"Order-of-magnitude cue: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume rise rate r=0.003 m/s and total data latency L=120 s.","failure":"常見誤解：「封包剛收到就一定代表此刻水位，無需再看量測時間。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A newly received packet necessarily represents current stage without checking observation time.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「傳輸延遲與資料時效」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Transmission latency and data age”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b269-v15-17-k1","title":"傳輸延遲與資料時效機理與驗證","titleEn":"Transmission latency and data age mechanism and verification","text":"自動遙測鏈包含感測、記錄、通訊、接收與發布，各段延遲相加才形成使用者看到的資料年齡。接收時間不等於量測時間，補傳舊封包更可能讓新到資料看似最新水位；洪水快速上升時，即使數值本身準確，過時資料仍可能造成錯誤情境判讀。","textEn":"An automated chain includes sensing, logging, communication, reception and publication; their delays determine the age of displayed information. Receipt time is not observation time, and retransmitted old packets can look deceptively current.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：封包剛收到就一定代表此刻水位，無需再看量測時間。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A newly received packet necessarily represents current stage without checking observation time. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"關於「傳輸延遲與資料時效機理與驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Transmission latency and data age mechanism and verification\" is correct?","options":["封包剛收到就一定代表此刻水位，無需再看量測時間。","裝好水位計後，任何洪水流量都能無誤差地自動換算。","自動遙測鏈包含感測、記錄、通訊、接收與發布，各段延遲相加才形成使用者看到的資料年齡。"],"optionsEn":["A newly received packet necessarily represents current stage without checking observation time.","Once a stage sensor is installed, every flood discharge converts automatically without error.","An automated chain includes sensing, logging, communication, reception and publication; their delays determine the age of displayed information."],"answer":2,"explanation":"自動遙測鏈包含感測、記錄、通訊、接收與發布，各段延遲相加才形成使用者看到的資料年齡。 其餘選項是常見誤解。","explanationEn":"An automated chain includes sensing, logging, communication, reception and publication; their delays determine the age of displayed information. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":17},{"id":"b269-v15-18","title":"傳輸延遲與資料時效機理與驗證：定量估算","titleEn":"Transmission latency and data age mechanism and verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-17"],"objective":"以數值模型估算「傳輸延遲與資料時效」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Transmission latency and data age” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設算例，以下量值用於簡化機理比較：假設水位上升率r=0.003 m/s、總資料延遲L=120 s，線性時效差Δh=rL=0.36 m。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume rise rate r=0.003 m/s and total data latency L=120 s. Linear age-related difference Δh=rL=0.36 m. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：保存量測、封包發送、接收與發布四種時間，使用一致時區和校時紀錄。","observationEn":"How to cross-check: Retain observation, transmission, receipt and publication times with consistent timezone and clock records.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b269-v15-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設算例，以下量值用於簡化機理比較：假設水位上升率r=0.003 m/s、總資料延遲L=120 s，線性時效差Δh=rL=0.36 m。","textEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume rise rate r=0.003 m/s and total data latency L=120 s. Linear age-related difference Δh=rL=0.36 m.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"依「傳輸延遲與資料時效機理與驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Transmission latency and data age mechanism and verification\", which statement holds?","options":["原創教學假設算例，以下量值用於簡化機理比較：假設水位上升率r=0.003 m/s、總資料延遲L=120 s，線性時效差Δh=rL=0.36 m。","感測器顯示到毫米，就代表水面絕對高程也準確到毫米。","只要現場裝兩支感測器，就一定可以把全部失效機率相乘。"],"optionsEn":["Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume rise rate r=0.003 m/s and total data latency L=120 s.","Millimeter display resolution means absolute water elevation is accurate to a millimeter.","Installing two field sensors always permits multiplication of all failure probabilities."],"answer":0,"explanation":"原創教學假設算例，以下量值用於簡化機理比較：假設水位上升率r=0.003 m/s、總資料延遲L=120 s，線性時效差Δh=rL=0.36 m。 重算時請保留單位。","explanationEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume rise rate r=0.003 m/s and total data latency L=120 s. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":18},{"id":"b269-v15-19","title":"傳輸延遲與資料時效機理與驗證：試驗與驗證","titleEn":"Transmission latency and data age mechanism and verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「傳輸延遲與資料時效」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Transmission latency and data age” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"保存量測、封包發送、接收與發布四種時間，使用一致時區和校時紀錄。透過測試封包量測端到端延遲分布，對補傳和過期資料加註旗標，避免只報平均延遲而漏掉長尾。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Retain observation, transmission, receipt and publication times with consistent timezone and clock records. Measure end-to-end latency distributions using test packets, flag backfilled and stale data, and inspect long delays rather than reporting only an average that hides the tail. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：畫出含一次補傳的時間線，分開標記觀測與發布順序。計算每筆資料年齡並制定畫面標示規則，說明哪些值只能補歷史而不能覆蓋最新狀態。","observationEn":"Site practice: Draw a timeline containing a retransmission, separating observation order from publication order. Calculate each record’s age and define display labels, explaining which records may fill history but must not replace the latest state.","failure":"注意干擾：用收到封包的時間覆蓋量測時間會把歷史水位當現況，時區錯置也可能產生假負延遲；只用平均通訊速度無法描述暴雨時的最長資料空窗。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Replacing observation time with receipt time presents historical stage as current, while timezone mistakes can create impossible negative latency. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b269-v15-19-k1","title":"驗證方法","titleEn":"Verification method","text":"保存量測、封包發送、接收與發布四種時間，使用一致時區和校時紀錄。透過測試封包量測端到端延遲分布，對補傳和過期資料加註旗標，避免只報平均延遲而漏掉長尾。","textEn":"Retain observation, transmission, receipt and publication times with consistent timezone and clock records. Measure end-to-end latency distributions using test packets, flag backfilled and stale data, and inspect long delays rather than reporting only an average that hides the tail.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-19-k2","title":"現場實務","titleEn":"Site practice","text":"畫出含一次補傳的時間線，分開標記觀測與發布順序。計算每筆資料年齡並制定畫面標示規則，說明哪些值只能補歷史而不能覆蓋最新狀態。","textEn":"Draw a timeline containing a retransmission, separating observation order from publication order. Calculate each record’s age and define display labels, explaining which records may fill history but must not replace the latest state.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"要驗證「傳輸延遲與資料時效機理與驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Transmission latency and data age mechanism and verification\"?","options":["允收準則可以等看到量測數據後再決定。","保存量測、封包發送、接收與發布四種時間，使用一致時區和校時紀錄。","任何壓力感測器輸出除以水重度就一定得到真實河川水深。"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Retain observation, transmission, receipt and publication times with consistent timezone and clock records.","Any pressure output divided by water unit weight gives true river depth."],"answer":1,"explanation":"保存量測、封包發送、接收與發布四種時間，使用一致時區和校時紀錄。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Retain observation, transmission, receipt and publication times with consistent timezone and clock records. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":19},{"id":"b269-v15-20","title":"傳輸延遲與資料時效機理與驗證：失效診斷","titleEn":"Transmission latency and data age mechanism and verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-19"],"objective":"從症狀倒推「傳輸延遲與資料時效」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Transmission latency and data age” and propose discriminating checks, corrective actions and prevention.","instruction":"用收到封包的時間覆蓋量測時間會把歷史水位當現況，時區錯置也可能產生假負延遲；只用平均通訊速度無法描述暴雨時的最長資料空窗。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Replacing observation time with receipt time presents historical stage as current, while timezone mistakes can create impossible negative latency. Average communication speed does not describe the longest information gaps during a storm. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：本例在固定上升速率下比較量測時與現在的差異，不是預報模型；真實加速度、回落及通訊中斷會破壞線性外推。","observationEn":"Link to the mechanism: It is not a forecast model; acceleration, recession and communication outages invalidate simple linear extrapolation.","failure":"誤判風險：若相信「封包剛收到就一定代表此刻水位，無需再看量測時間。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A newly received packet necessarily represents current stage without checking observation time.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b269-v15-20-k1","title":"失效模式","titleEn":"Failure mode","text":"用收到封包的時間覆蓋量測時間會把歷史水位當現況，時區錯置也可能產生假負延遲；只用平均通訊速度無法描述暴雨時的最長資料空窗。","textEn":"Replacing observation time with receipt time presents historical stage as current, while timezone mistakes can create impossible negative latency. Average communication speed does not describe the longest information gaps during a storm.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"在「傳輸延遲與資料時效機理與驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Transmission latency and data age mechanism and verification\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","裝好水位計後，任何洪水流量都能無誤差地自動換算。","用收到封包的時間覆蓋量測時間會把歷史水位當現況，時區錯置也可能產生假負延遲；只用平均通訊速度無法描述暴雨時的最長資料空窗。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","Once a stage sensor is installed, every flood discharge converts automatically without error.","Replacing observation time with receipt time presents historical stage as current, while timezone mistakes can create impossible negative latency."],"answer":2,"explanation":"用收到封包的時間覆蓋量測時間會把歷史水位當現況，時區錯置也可能產生假負延遲；只用平均通訊速度無法描述暴雨時的最長資料空窗。 需以量測區分可能原因。","explanationEn":"Replacing observation time with receipt time presents historical stage as current, while timezone mistakes can create impossible negative latency. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":20},{"id":"b269-v15-21","title":"水位流量關係與外推機理與驗證：機制與系統路徑","titleEn":"Stage-discharge relation and extrapolation mechanism and verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-20"],"objective":"說明「水位流量關係與外推」如何影響河川水位自動遙測的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Stage-discharge relation and extrapolation” governs forces, deformation, flow or signals in “Automatic river-level telemetry”, and map the relevant inputs, transfer paths and boundaries.","instruction":"河川水位轉成流量通常依現地率定關係，控制斷面、糙率及回水變化會讓同一水位對應不同流量。漲退水遲滯與下游潮位可能使單值曲線失效；因此水位遙測完成不代表流量已直接量到，率定版本、有效範圍與量測支撐必須隨資料一起提供。本例採指定單值冪次曲線並明列係數單位，限定有效水頭為正；不是實站率定，也不應外推到回水或河床劇變情境。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「水位流量關係與外推」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Converting stage to discharge normally uses a site-calibrated relation whose behavior depends on channel control, roughness and backwater. Rising/falling hysteresis and downstream tide can give different flows at the same stage. Automated stage measurement therefore does not mean discharge was directly measured; rating version, valid range and supporting observations must accompany derived flow. The example specifies a single-valued power rating with coefficient units and positive effective head. It is not a real station rating and should not be extrapolated into backwater or major bed change. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Stage-discharge relation and extrapolation” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設算例，以下量值用於簡化機理比較：假設Q=a(h−h0)^b，a=20 m^1.4/s、b=1.6、h=2.0 m、h0=0.5 m，Q=38.26 m³/s。","observationEn":"Order-of-magnitude cue: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume Q=a(h−h0)^b, a=20 m^1.4/s, b=1.6, h=2.0 m and h0=0.5 m.","failure":"常見誤解：「裝好水位計後，任何洪水流量都能無誤差地自動換算。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Once a stage sensor is installed, every flood discharge converts automatically without error.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「水位流量關係與外推」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Stage-discharge relation and extrapolation”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b269-v15-21-k1","title":"水位流量關係與外推機理與驗證","titleEn":"Stage-discharge relation and extrapolation mechanism and verification","text":"河川水位轉成流量通常依現地率定關係，控制斷面、糙率及回水變化會讓同一水位對應不同流量。漲退水遲滯與下游潮位可能使單值曲線失效；因此水位遙測完成不代表流量已直接量到，率定版本、有效範圍與量測支撐必須隨資料一起提供。","textEn":"Converting stage to discharge normally uses a site-calibrated relation whose behavior depends on channel control, roughness and backwater. Rising/falling hysteresis and downstream tide can give different flows at the same stage.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：裝好水位計後，任何洪水流量都能無誤差地自動換算。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Once a stage sensor is installed, every flood discharge converts automatically without error. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"關於「水位流量關係與外推機理與驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Stage-discharge relation and extrapolation mechanism and verification\" is correct?","options":["河川水位轉成流量通常依現地率定關係，控制斷面、糙率及回水變化會讓同一水位對應不同流量。","裝好水位計後，任何洪水流量都能無誤差地自動換算。","取樣越密，任何相鄰兩點差分得到的水位速率就一定越可靠。"],"optionsEn":["Converting stage to discharge normally uses a site-calibrated relation whose behavior depends on channel control, roughness and backwater.","Once a stage sensor is installed, every flood discharge converts automatically without error.","Denser sampling always makes a two-point stage derivative more reliable."],"answer":0,"explanation":"河川水位轉成流量通常依現地率定關係，控制斷面、糙率及回水變化會讓同一水位對應不同流量。 其餘選項是常見誤解。","explanationEn":"Converting stage to discharge normally uses a site-calibrated relation whose behavior depends on channel control, roughness and backwater. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":21},{"id":"b269-v15-22","title":"水位流量關係與外推機理與驗證：定量估算","titleEn":"Stage-discharge relation and extrapolation mechanism and verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-21"],"objective":"以數值模型估算「水位流量關係與外推」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Stage-discharge relation and extrapolation” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設算例，以下量值用於簡化機理比較：假設Q=a(h−h0)^b，a=20 m^1.4/s、b=1.6、h=2.0 m、h0=0.5 m，Q=38.26 m³/s。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume Q=a(h−h0)^b, a=20 m^1.4/s, b=1.6, h=2.0 m and h0=0.5 m. Discharge Q=38.26 m³/s. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以獨立流量量測覆蓋漲退水及不同水位，檢查殘差是否與下游水位或時間有系統關係。","observationEn":"How to cross-check: Use independent discharge measurements across stages and both hydrograph limbs, checking whether residuals depend systematically on downstream level or time.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b269-v15-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設算例，以下量值用於簡化機理比較：假設Q=a(h−h0)^b，a=20 m^1.4/s、b=1.6、h=2.0 m、h0=0.5 m，Q=38.26 m³/s。","textEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume Q=a(h−h0)^b, a=20 m^1.4/s, b=1.6, h=2.0 m and h0=0.5 m. Discharge Q=38.26 m³/s.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"依「水位流量關係與外推機理與驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Stage-discharge relation and extrapolation mechanism and verification\", which statement holds?","options":["電池安培小時越大就可直接比較續航，不需要知道電壓或負載。","原創教學假設算例，以下量值用於簡化機理比較：假設Q=a(h−h0)^b，a=20 m^1.4/s、b=1.6、h=2.0 m、h0=0.5 m，Q=38.26 m³/s。","所有水位計顯示的公尺數都已是同一海拔基準下的高程。"],"optionsEn":["Battery ampere-hours alone compare endurance without voltage or load information.","Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume Q=a(h−h0)^b, a=20 m^1.4/s, b=1.6, h=2.0 m and h0=0.5 m.","Every water-level reading in meters already uses the same sea-level datum."],"answer":1,"explanation":"原創教學假設算例，以下量值用於簡化機理比較：假設Q=a(h−h0)^b，a=20 m^1.4/s、b=1.6、h=2.0 m、h0=0.5 m，Q=38.26 m³/s。 重算時請保留單位。","explanationEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume Q=a(h−h0)^b, a=20 m^1.4/s, b=1.6, h=2.0 m and h0=0.5 m. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":22},{"id":"b269-v15-23","title":"水位流量關係與外推機理與驗證：試驗與驗證","titleEn":"Stage-discharge relation and extrapolation mechanism and verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「水位流量關係與外推」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Stage-discharge relation and extrapolation” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以獨立流量量測覆蓋漲退水及不同水位，檢查殘差是否與下游水位或時間有系統關係。保存率定版本和外推旗標，洪水後重新查控制斷面，而不是只調係數追求漂亮擬合。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use independent discharge measurements across stages and both hydrograph limbs, checking whether residuals depend systematically on downstream level or time. Retain rating versions and extrapolation flags, and resurvey channel control after floods instead of merely adjusting coefficients for an attractive fit. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：用指定曲線計算兩個水位，標出有效水頭與係數單位。再畫出相同水位有兩個流量的遲滯示意，說明需要增加哪種觀測才能區分兩支曲線。","observationEn":"Site practice: Calculate two discharges from the specified rating, labeling effective head and coefficient units. Draw a hysteresis example with two flows at one stage and explain what additional observation could distinguish the two branches.","failure":"注意干擾：把超出量測範圍的曲線延伸當實測會低估高水位不確定度，河床沖淤後沿用舊率定也可能產生系統偏差；單點水位無法唯一解決強回水流量。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Calling an extrapolated curve measured flow understates high-stage uncertainty, and using an old rating after bed change introduces bias. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b269-v15-23-k1","title":"驗證方法","titleEn":"Verification method","text":"以獨立流量量測覆蓋漲退水及不同水位，檢查殘差是否與下游水位或時間有系統關係。保存率定版本和外推旗標，洪水後重新查控制斷面，而不是只調係數追求漂亮擬合。","textEn":"Use independent discharge measurements across stages and both hydrograph limbs, checking whether residuals depend systematically on downstream level or time. Retain rating versions and extrapolation flags, and resurvey channel control after floods instead of merely adjusting coefficients for an attractive fit.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-23-k2","title":"現場實務","titleEn":"Site practice","text":"用指定曲線計算兩個水位，標出有效水頭與係數單位。再畫出相同水位有兩個流量的遲滯示意，說明需要增加哪種觀測才能區分兩支曲線。","textEn":"Calculate two discharges from the specified rating, labeling effective head and coefficient units. Draw a hysteresis example with two flows at one stage and explain what additional observation could distinguish the two branches.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"要驗證「水位流量關係與外推機理與驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Stage-discharge relation and extrapolation mechanism and verification\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","雷達不接觸水，所以不需要高程測量或現地水尺交叉驗證。","以獨立流量量測覆蓋漲退水及不同水位，檢查殘差是否與下游水位或時間有系統關係。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","Noncontact radar needs neither elevation surveying nor field staff-gage checks.","Use independent discharge measurements across stages and both hydrograph limbs, checking whether residuals depend systematically on downstream level or time."],"answer":2,"explanation":"以獨立流量量測覆蓋漲退水及不同水位，檢查殘差是否與下游水位或時間有系統關係。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use independent discharge measurements across stages and both hydrograph limbs, checking whether residuals depend systematically on downstream level or time. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":23},{"id":"b269-v15-24","title":"水位流量關係與外推機理與驗證：失效診斷","titleEn":"Stage-discharge relation and extrapolation mechanism and verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-23"],"objective":"從症狀倒推「水位流量關係與外推」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Stage-discharge relation and extrapolation” and propose discriminating checks, corrective actions and prevention.","instruction":"把超出量測範圍的曲線延伸當實測會低估高水位不確定度，河床沖淤後沿用舊率定也可能產生系統偏差；單點水位無法唯一解決強回水流量。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Calling an extrapolated curve measured flow understates high-stage uncertainty, and using an old rating after bed change introduces bias. One stage observation cannot uniquely resolve discharge under strong backwater. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：本例採指定單值冪次曲線並明列係數單位，限定有效水頭為正；不是實站率定，也不應外推到回水或河床劇變情境。","observationEn":"Link to the mechanism: It is not a real station rating and should not be extrapolated into backwater or major bed change.","failure":"誤判風險：若相信「裝好水位計後，任何洪水流量都能無誤差地自動換算。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Once a stage sensor is installed, every flood discharge converts automatically without error.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b269-v15-24-k1","title":"失效模式","titleEn":"Failure mode","text":"把超出量測範圍的曲線延伸當實測會低估高水位不確定度，河床沖淤後沿用舊率定也可能產生系統偏差；單點水位無法唯一解決強回水流量。","textEn":"Calling an extrapolated curve measured flow understates high-stage uncertainty, and using an old rating after bed change introduces bias. One stage observation cannot uniquely resolve discharge under strong backwater.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"在「水位流量關係與外推機理與驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Stage-discharge relation and extrapolation mechanism and verification\" shows distress, which diagnosis is most reasonable?","options":["把超出量測範圍的曲線延伸當實測會低估高水位不確定度，河床沖淤後沿用舊率定也可能產生系統偏差；單點水位無法唯一解決強回水流量。","只要結構還沒倒，就代表安全餘裕仍然足夠。","取樣越密，任何相鄰兩點差分得到的水位速率就一定越可靠。"],"optionsEn":["Calling an extrapolated curve measured flow understates high-stage uncertainty, and using an old rating after bed change introduces bias.","As long as the structure is still standing, its safety margin must still be adequate.","Denser sampling always makes a two-point stage derivative more reliable."],"answer":0,"explanation":"把超出量測範圍的曲線延伸當實測會低估高水位不確定度，河床沖淤後沿用舊率定也可能產生系統偏差；單點水位無法唯一解決強回水流量。 需以量測區分可能原因。","explanationEn":"Calling an extrapolated curve measured flow understates high-stage uncertainty, and using an old rating after bed change introduces bias. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":24}],"order":3},{"id":"b269-v15-s4","title":"試驗、量測與監測驗證","titleEn":"Testing, measurement and monitoring","description":"本階段聚焦「上升速率與雜訊機理與驗證」與「高程不確定度合成機理與驗證」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Rise-rate estimation and noise mechanism and verification\" and \"Elevation uncertainty combination mechanism and verification\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b269-v15-25","title":"上升速率與雜訊機理與驗證：機制與系統路徑","titleEn":"Rise-rate estimation and noise mechanism and verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-24"],"objective":"說明「上升速率與雜訊」如何影響河川水位自動遙測的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Rise-rate estimation and noise” governs forces, deformation, flow or signals in “Automatic river-level telemetry”, and map the relevant inputs, transfer paths and boundaries.","instruction":"水位上升速率能補充絕對水位資訊，但差分運算會放大量測雜訊和時間誤差。取樣間隔越短，並不保證速率越準確；過度平滑雖降低雜訊卻延遲急升訊號，因此應將原始資料、濾波方式和速率計算窗分開保存，避免用單一尖峰差分觸發無法解釋的判斷。本例計算兩筆有效讀值間的平均變化率，不代表區間內瞬時最大值；警戒規則與多源確認需另按實際防洪系統制定。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「上升速率與雜訊」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Rise rate supplements absolute stage, but differencing amplifies measurement noise and timing errors. A shorter interval does not guarantee a more accurate derivative. Heavy smoothing reduces noise while delaying rapid-rise signals, so raw data, filtering method and derivative window should remain separately documented rather than relying on an unexplained single-sample spike. The example is the mean rate between two valid readings, not the maximum instantaneous rate within the interval. Warning rules and multisource confirmation require a separate operational framework. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Rise-rate estimation and noise” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設算例，以下量值用於簡化機理比較：假設水位由2.10升至2.22 m、間隔Δt=600 s，平均r=0.12/600=0.00020 m/s=0.72 m/h。","observationEn":"Order-of-magnitude cue: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume stage rises from 2.10 to 2.22 m over Δt=600 s.","failure":"常見誤解：「取樣越密，任何相鄰兩點差分得到的水位速率就一定越可靠。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Denser sampling always makes a two-point stage derivative more reliable.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「上升速率與雜訊」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Rise-rate estimation and noise”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b269-v15-25-k1","title":"上升速率與雜訊機理與驗證","titleEn":"Rise-rate estimation and noise mechanism and verification","text":"水位上升速率能補充絕對水位資訊，但差分運算會放大量測雜訊和時間誤差。取樣間隔越短，並不保證速率越準確；過度平滑雖降低雜訊卻延遲急升訊號，因此應將原始資料、濾波方式和速率計算窗分開保存，避免用單一尖峰差分觸發無法解釋的判斷。","textEn":"Rise rate supplements absolute stage, but differencing amplifies measurement noise and timing errors. A shorter interval does not guarantee a more accurate derivative.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：取樣越密，任何相鄰兩點差分得到的水位速率就一定越可靠。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Denser sampling always makes a two-point stage derivative more reliable. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"關於「上升速率與雜訊機理與驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Rise-rate estimation and noise mechanism and verification\" is correct?","options":["取樣越密，任何相鄰兩點差分得到的水位速率就一定越可靠。","水位上升速率能補充絕對水位資訊，但差分運算會放大量測雜訊和時間誤差。","感測器顯示到毫米，就代表水面絕對高程也準確到毫米。"],"optionsEn":["Denser sampling always makes a two-point stage derivative more reliable.","Rise rate supplements absolute stage, but differencing amplifies measurement noise and timing errors.","Millimeter display resolution means absolute water elevation is accurate to a millimeter."],"answer":1,"explanation":"水位上升速率能補充絕對水位資訊，但差分運算會放大量測雜訊和時間誤差。 其餘選項是常見誤解。","explanationEn":"Rise rate supplements absolute stage, but differencing amplifies measurement noise and timing errors. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b269-v15-26","title":"上升速率與雜訊機理與驗證：定量估算","titleEn":"Rise-rate estimation and noise mechanism and verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-25"],"objective":"以數值模型估算「上升速率與雜訊」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Rise-rate estimation and noise” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設算例，以下量值用於簡化機理比較：假設水位由2.10升至2.22 m、間隔Δt=600 s，平均r=0.12/600=0.00020 m/s=0.72 m/h。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume stage rises from 2.10 to 2.22 m over Δt=600 s. Mean r=0.12/600=0.00020 m/s=0.72 m/h. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：檢查兩筆資料的品質旗標、實際時間差及是否跨越零點改正，再比較不同窗長的速率。","observationEn":"How to cross-check: Check quality flags, actual time separation and any intervening datum correction, then compare rates from different windows.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b269-v15-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設算例，以下量值用於簡化機理比較：假設水位由2.10升至2.22 m、間隔Δt=600 s，平均r=0.12/600=0.00020 m/s=0.72 m/h。","textEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume stage rises from 2.10 to 2.22 m over Δt=600 s. Mean r=0.12/600=0.00020 m/s=0.72 m/h.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"依「上升速率與雜訊機理與驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Rise-rate estimation and noise mechanism and verification\", which statement holds?","options":["只要現場裝兩支感測器，就一定可以把全部失效機率相乘。","任何壓力感測器輸出除以水重度就一定得到真實河川水深。","原創教學假設算例，以下量值用於簡化機理比較：假設水位由2.10升至2.22 m、間隔Δt=600 s，平均r=0.12/600=0.00020 m/s=0.72 m/h。"],"optionsEn":["Installing two field sensors always permits multiplication of all failure probabilities.","Any pressure output divided by water unit weight gives true river depth.","Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume stage rises from 2.10 to 2.22 m over Δt=600 s."],"answer":2,"explanation":"原創教學假設算例，以下量值用於簡化機理比較：假設水位由2.10升至2.22 m、間隔Δt=600 s，平均r=0.12/600=0.00020 m/s=0.72 m/h。 重算時請保留單位。","explanationEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume stage rises from 2.10 to 2.22 m over Δt=600 s. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":26},{"id":"b269-v15-27","title":"上升速率與雜訊機理與驗證：試驗與驗證","titleEn":"Rise-rate estimation and noise mechanism and verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「上升速率與雜訊」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Rise-rate estimation and noise” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"檢查兩筆資料的品質旗標、實際時間差及是否跨越零點改正，再比較不同窗長的速率。用已知事件或合成訊號量測濾波延遲，將可接受雜訊與漏失急升的取捨明確記錄。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check quality flags, actual time separation and any intervening datum correction, then compare rates from different windows. Measure filter delay with known events or synthetic signals, explicitly recording the tradeoff between tolerated noise and missed or delayed rapid rises. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：給兩筆水位加入正負一公分誤差，比較短窗和長窗的速率偏差。另以快速上升訊號測試移動平均，說明減噪與延遲不能只用同一個指標評分。","observationEn":"Site practice: Add opposite one-centimeter errors to two readings and compare rate bias over short and long windows. Test a moving average on a rapid rise and explain why noise reduction and delay need separate evaluation metrics.","failure":"注意干擾：兩個相鄰讀值的小誤差經短時間差相除可變成巨大速率，跨越零點調整也會形成假急升；過度濾波則可能把真實快速上漲延後呈現。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Small adjacent-reading errors divided by a short interval can create a large apparent rate, and a datum adjustment can mimic a surge. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b269-v15-27-k1","title":"驗證方法","titleEn":"Verification method","text":"檢查兩筆資料的品質旗標、實際時間差及是否跨越零點改正，再比較不同窗長的速率。用已知事件或合成訊號量測濾波延遲，將可接受雜訊與漏失急升的取捨明確記錄。","textEn":"Check quality flags, actual time separation and any intervening datum correction, then compare rates from different windows. Measure filter delay with known events or synthetic signals, explicitly recording the tradeoff between tolerated noise and missed or delayed rapid rises.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-27-k2","title":"現場實務","titleEn":"Site practice","text":"給兩筆水位加入正負一公分誤差，比較短窗和長窗的速率偏差。另以快速上升訊號測試移動平均，說明減噪與延遲不能只用同一個指標評分。","textEn":"Add opposite one-centimeter errors to two readings and compare rate bias over short and long windows. Test a moving average on a rapid rise and explain why noise reduction and delay need separate evaluation metrics.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"要驗證「上升速率與雜訊機理與驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Rise-rate estimation and noise mechanism and verification\"?","options":["檢查兩筆資料的品質旗標、實際時間差及是否跨越零點改正，再比較不同窗長的速率。","量測時不必記錄溫度、水頭、水位歷程與施工荷重，因為它們不會影響結果。","只要圖表每秒重畫，就代表河川每秒都有一筆新量測。"],"optionsEn":["Check quality flags, actual time separation and any intervening datum correction, then compare rates from different windows.","Temperature, water head, water-level history and construction loads need not be recorded because they cannot affect the result.","A graph refreshed every second means the river has a new measurement every second."],"answer":0,"explanation":"檢查兩筆資料的品質旗標、實際時間差及是否跨越零點改正，再比較不同窗長的速率。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check quality flags, actual time separation and any intervening datum correction, then compare rates from different windows. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":27},{"id":"b269-v15-28","title":"上升速率與雜訊機理與驗證：失效診斷","titleEn":"Rise-rate estimation and noise mechanism and verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-27"],"objective":"從症狀倒推「上升速率與雜訊」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Rise-rate estimation and noise” and propose discriminating checks, corrective actions and prevention.","instruction":"兩個相鄰讀值的小誤差經短時間差相除可變成巨大速率，跨越零點調整也會形成假急升；過度濾波則可能把真實快速上漲延後呈現。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Small adjacent-reading errors divided by a short interval can create a large apparent rate, and a datum adjustment can mimic a surge. Excessive filtering can instead display a genuine rapid rise too late. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：本例計算兩筆有效讀值間的平均變化率，不代表區間內瞬時最大值；警戒規則與多源確認需另按實際防洪系統制定。","observationEn":"Link to the mechanism: Warning rules and multisource confirmation require a separate operational framework.","failure":"誤判風險：若相信「取樣越密，任何相鄰兩點差分得到的水位速率就一定越可靠。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Denser sampling always makes a two-point stage derivative more reliable.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b269-v15-28-k1","title":"失效模式","titleEn":"Failure mode","text":"兩個相鄰讀值的小誤差經短時間差相除可變成巨大速率，跨越零點調整也會形成假急升；過度濾波則可能把真實快速上漲延後呈現。","textEn":"Small adjacent-reading errors divided by a short interval can create a large apparent rate, and a datum adjustment can mimic a surge. Excessive filtering can instead display a genuine rapid rise too late.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"在「上升速率與雜訊機理與驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Rise-rate estimation and noise mechanism and verification\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","兩個相鄰讀值的小誤差經短時間差相除可變成巨大速率，跨越零點調整也會形成假急升；過度濾波則可能把真實快速上漲延後呈現。","感測器顯示到毫米，就代表水面絕對高程也準確到毫米。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Small adjacent-reading errors divided by a short interval can create a large apparent rate, and a datum adjustment can mimic a surge.","Millimeter display resolution means absolute water elevation is accurate to a millimeter."],"answer":1,"explanation":"兩個相鄰讀值的小誤差經短時間差相除可變成巨大速率，跨越零點調整也會形成假急升；過度濾波則可能把真實快速上漲延後呈現。 需以量測區分可能原因。","explanationEn":"Small adjacent-reading errors divided by a short interval can create a large apparent rate, and a datum adjustment can mimic a surge. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":28},{"id":"b269-v15-29","title":"高程不確定度合成機理與驗證：機制與系統路徑","titleEn":"Elevation uncertainty combination mechanism and verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-28"],"objective":"說明「高程不確定度合成」如何影響河川水位自動遙測的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Elevation uncertainty combination” governs forces, deformation, flow or signals in “Automatic river-level telemetry”, and map the relevant inputs, transfer paths and boundaries.","instruction":"自動水位高程包含感測、基準連接和安裝幾何等不確定度，顯示小數位數不代表同樣程度的可信度。獨立隨機項可用平方和合成，但共同基準偏差、漂移及未修正系統誤差不能隨意當成獨立量；報告需區分標準不確定度、擴展區間與誤差來源，而不是只給一個精度標籤。下式只合成兩個指定獨立標準不確定度，沒有乘涵蓋因子；不能把結果直接稱為百分之九十五信賴區間或量測閉合差。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「高程不確定度合成」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Automated elevation combines sensor, datum-transfer and installation-geometry uncertainty, and display decimals do not imply equal confidence. Independent random contributions can be combined by root-sum-square, but shared datum bias, drift and uncorrected systematic error cannot simply be treated as independent. Reports should distinguish standard uncertainty, expanded intervals and contributing sources rather than provide one vague accuracy label. The expression combines two specified independent standard uncertainties without a coverage factor. It is neither automatically a 95-percent interval nor a measured leveling closure error. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Elevation uncertainty combination” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設算例，以下量值用於簡化機理比較：假設感測標準不確定度us=0.010 m、基準連接ud=0.020 m且獨立，uc=√(us²+ud²)=0.02236 m。","observationEn":"Order-of-magnitude cue: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume independent sensor uncertainty us=0.010 m and datum-transfer uncertainty ud=0.020 m.","failure":"常見誤解：「感測器顯示到毫米，就代表水面絕對高程也準確到毫米。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Millimeter display resolution means absolute water elevation is accurate to a millimeter.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「高程不確定度合成」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Elevation uncertainty combination”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b269-v15-29-k1","title":"高程不確定度合成機理與驗證","titleEn":"Elevation uncertainty combination mechanism and verification","text":"自動水位高程包含感測、基準連接和安裝幾何等不確定度，顯示小數位數不代表同樣程度的可信度。獨立隨機項可用平方和合成，但共同基準偏差、漂移及未修正系統誤差不能隨意當成獨立量；報告需區分標準不確定度、擴展區間與誤差來源，而不是只給一個精度標籤。","textEn":"Automated elevation combines sensor, datum-transfer and installation-geometry uncertainty, and display decimals do not imply equal confidence. Independent random contributions can be combined by root-sum-square, but shared datum bias, drift and uncorrected systematic error cannot simply be treated as independent.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：感測器顯示到毫米，就代表水面絕對高程也準確到毫米。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Millimeter display resolution means absolute water elevation is accurate to a millimeter. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"關於「高程不確定度合成機理與驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Elevation uncertainty combination mechanism and verification\" is correct?","options":["感測器顯示到毫米，就代表水面絕對高程也準確到毫米。","電池安培小時越大就可直接比較續航，不需要知道電壓或負載。","自動水位高程包含感測、基準連接和安裝幾何等不確定度，顯示小數位數不代表同樣程度的可信度。"],"optionsEn":["Millimeter display resolution means absolute water elevation is accurate to a millimeter.","Battery ampere-hours alone compare endurance without voltage or load information.","Automated elevation combines sensor, datum-transfer and installation-geometry uncertainty, and display decimals do not imply equal confidence."],"answer":2,"explanation":"自動水位高程包含感測、基準連接和安裝幾何等不確定度，顯示小數位數不代表同樣程度的可信度。 其餘選項是常見誤解。","explanationEn":"Automated elevation combines sensor, datum-transfer and installation-geometry uncertainty, and display decimals do not imply equal confidence. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b269-v15-30","title":"高程不確定度合成機理與驗證：定量估算","titleEn":"Elevation uncertainty combination mechanism and verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-29"],"objective":"以數值模型估算「高程不確定度合成」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Elevation uncertainty combination” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設算例，以下量值用於簡化機理比較：假設感測標準不確定度us=0.010 m、基準連接ud=0.020 m且獨立，uc=√(us²+ud²)=0.02236 m。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume independent sensor uncertainty us=0.010 m and datum-transfer uncertainty ud=0.020 m. Combined standard uc=√(us²+ud²)=0.02236 m. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：建立誤差來源表，列明每項來自校正、重複量測或幾何估計，以及是否共享參考。","observationEn":"How to cross-check: Build a source table identifying calibration, repeat measurement or geometric estimation and shared references.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b269-v15-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設算例，以下量值用於簡化機理比較：假設感測標準不確定度us=0.010 m、基準連接ud=0.020 m且獨立，uc=√(us²+ud²)=0.02236 m。","textEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume independent sensor uncertainty us=0.010 m and datum-transfer uncertainty ud=0.020 m. Combined standard uc=√(us²+ud²)=0.02236 m.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"依「高程不確定度合成機理與驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Elevation uncertainty combination mechanism and verification\", which statement holds?","options":["原創教學假設算例，以下量值用於簡化機理比較：假設感測標準不確定度us=0.010 m、基準連接ud=0.020 m且獨立，uc=√(us²+ud²)=0.02236 m。","所有水位計顯示的公尺數都已是同一海拔基準下的高程。","雷達不接觸水，所以不需要高程測量或現地水尺交叉驗證。"],"optionsEn":["Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume independent sensor uncertainty us=0.010 m and datum-transfer uncertainty ud=0.020 m.","Every water-level reading in meters already uses the same sea-level datum.","Noncontact radar needs neither elevation surveying nor field staff-gage checks."],"answer":0,"explanation":"原創教學假設算例，以下量值用於簡化機理比較：假設感測標準不確定度us=0.010 m、基準連接ud=0.020 m且獨立，uc=√(us²+ud²)=0.02236 m。 重算時請保留單位。","explanationEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume independent sensor uncertainty us=0.010 m and datum-transfer uncertainty ud=0.020 m. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":30},{"id":"b269-v15-31","title":"高程不確定度合成機理與驗證：試驗與驗證","titleEn":"Elevation uncertainty combination mechanism and verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「高程不確定度合成」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Elevation uncertainty combination” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"建立誤差來源表，列明每項來自校正、重複量測或幾何估計，以及是否共享參考。檢查偏差是否已改正，將標準不確定度和實際水準閉合值分開，必要時保留相關係數再合成。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Build a source table identifying calibration, repeat measurement or geometric estimation and shared references. Check whether bias has been corrected, keep standard uncertainty distinct from actual leveling closure, and retain covariance terms where dependence prevents a simple independent combination. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將一份誤差表分成獨立與共用來源，先合成可獨立的項，再討論共用基準如何影響兩站高差。寫出包含單位和涵蓋說明的完整結果句。","observationEn":"Site practice: Separate independent and shared sources, combine only eligible terms, then discuss how a shared datum affects a two-station elevation difference. Write a complete result sentence with units and an explicit statement about coverage.","failure":"注意干擾：把共同基準誤差當兩個獨立項可能錯估比較結果，增加取樣也無法消除固定偏差；將平方和結果直接標為最大誤差則又混淆機率尺度與保證界限。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Treating shared datum error as independent can misstate a comparison, and more samples do not remove fixed bias. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b269-v15-31-k1","title":"驗證方法","titleEn":"Verification method","text":"建立誤差來源表，列明每項來自校正、重複量測或幾何估計，以及是否共享參考。檢查偏差是否已改正，將標準不確定度和實際水準閉合值分開，必要時保留相關係數再合成。","textEn":"Build a source table identifying calibration, repeat measurement or geometric estimation and shared references. Check whether bias has been corrected, keep standard uncertainty distinct from actual leveling closure, and retain covariance terms where dependence prevents a simple independent combination.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-31-k2","title":"現場實務","titleEn":"Site practice","text":"將一份誤差表分成獨立與共用來源，先合成可獨立的項，再討論共用基準如何影響兩站高差。寫出包含單位和涵蓋說明的完整結果句。","textEn":"Separate independent and shared sources, combine only eligible terms, then discuss how a shared datum affects a two-station elevation difference. Write a complete result sentence with units and an explicit statement about coverage.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"要驗證「高程不確定度合成機理與驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Elevation uncertainty combination mechanism and verification\"?","options":["沿用另一處水工設施或流域的量測結果，就可視為本工程已完成驗證。","建立誤差來源表，列明每項來自校正、重複量測或幾何估計，以及是否共享參考。","封包剛收到就一定代表此刻水位，無需再看量測時間。"],"optionsEn":["Reusing results from another hydraulic structure or catchment counts as verifying this structure.","Build a source table identifying calibration, repeat measurement or geometric estimation and shared references.","A newly received packet necessarily represents current stage without checking observation time."],"answer":1,"explanation":"建立誤差來源表，列明每項來自校正、重複量測或幾何估計，以及是否共享參考。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Build a source table identifying calibration, repeat measurement or geometric estimation and shared references. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":31},{"id":"b269-v15-32","title":"高程不確定度合成機理與驗證：失效診斷","titleEn":"Elevation uncertainty combination mechanism and verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-31"],"objective":"從症狀倒推「高程不確定度合成」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Elevation uncertainty combination” and propose discriminating checks, corrective actions and prevention.","instruction":"把共同基準誤差當兩個獨立項可能錯估比較結果，增加取樣也無法消除固定偏差；將平方和結果直接標為最大誤差則又混淆機率尺度與保證界限。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Treating shared datum error as independent can misstate a comparison, and more samples do not remove fixed bias. Labeling a root-sum-square result as maximum error further confuses a probabilistic scale with a guaranteed bound. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：下式只合成兩個指定獨立標準不確定度，沒有乘涵蓋因子；不能把結果直接稱為百分之九十五信賴區間或量測閉合差。","observationEn":"Link to the mechanism: It is neither automatically a 95-percent interval nor a measured leveling closure error.","failure":"誤判風險：若相信「感測器顯示到毫米，就代表水面絕對高程也準確到毫米。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Millimeter display resolution means absolute water elevation is accurate to a millimeter.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b269-v15-32-k1","title":"失效模式","titleEn":"Failure mode","text":"把共同基準誤差當兩個獨立項可能錯估比較結果，增加取樣也無法消除固定偏差；將平方和結果直接標為最大誤差則又混淆機率尺度與保證界限。","textEn":"Treating shared datum error as independent can misstate a comparison, and more samples do not remove fixed bias. Labeling a root-sum-square result as maximum error further confuses a probabilistic scale with a guaranteed bound.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"在「高程不確定度合成機理與驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Elevation uncertainty combination mechanism and verification\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","電池安培小時越大就可直接比較續航，不需要知道電壓或負載。","把共同基準誤差當兩個獨立項可能錯估比較結果，增加取樣也無法消除固定偏差；將平方和結果直接標為最大誤差則又混淆機率尺度與保證界限。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Battery ampere-hours alone compare endurance without voltage or load information.","Treating shared datum error as independent can misstate a comparison, and more samples do not remove fixed bias."],"answer":2,"explanation":"把共同基準誤差當兩個獨立項可能錯估比較結果，增加取樣也無法消除固定偏差；將平方和結果直接標為最大誤差則又混淆機率尺度與保證界限。 需以量測區分可能原因。","explanationEn":"Treating shared datum error as independent can misstate a comparison, and more samples do not remove fixed bias. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":32}],"order":4},{"id":"b269-v15-s5","title":"耐久、維護與工程交接","titleEn":"Durability, maintenance and engineering handoff","description":"本階段聚焦「備援電源與能量帳機理與驗證」與「獨立備援與共因失效機理與驗證」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Backup power and energy budget mechanism and verification\" and \"Independent redundancy and common causes mechanism and verification\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b269-v15-33","title":"備援電源與能量帳機理與驗證：機制與系統路徑","titleEn":"Backup power and energy budget mechanism and verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-32"],"objective":"說明「備援電源與能量帳」如何影響河川水位自動遙測的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Backup power and energy budget” governs forces, deformation, flow or signals in “Automatic river-level telemetry”, and map the relevant inputs, transfer paths and boundaries.","instruction":"偏遠測站的可用時間取決於平均負載、通訊脈衝、電池可用容量及環境條件，不能只看安培小時數。電壓換算、允許放電深度和電源轉換損失都影響可用能量，低溫與老化又可能降低容量；太陽能日均供電也無法單獨保證連續陰雨期間仍有資料。本例以固定平均負載與指定可用係數作能量比較，忽略自放電、老化和低溫；計算時數不是實站續航保證。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「備援電源與能量帳」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Remote-station endurance depends on average load, transmission pulses, usable battery capacity and environment rather than ampere-hours alone. Voltage, allowed depth of discharge and conversion losses determine useful energy, while cold and aging may reduce capacity. Mean solar input likewise cannot guarantee observations throughout an extended cloudy period. The example uses fixed mean load and specified usable factors, excluding self-discharge, aging and cold. Calculated hours are an energy comparison, not a station-endurance guarantee. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Backup power and energy budget” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設算例，以下量值用於簡化機理比較：假設電池12 V、40 Ah、可用放電比例0.50、轉換效率0.85、平均負載2 W，續航t=12×40×0.50×0.85/2=102 h。","observationEn":"Order-of-magnitude cue: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume battery 12 V, 40 Ah, usable discharge fraction 0.50, conversion efficiency 0.85 and mean load 2 W.","failure":"常見誤解：「電池安培小時越大就可直接比較續航，不需要知道電壓或負載。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Battery ampere-hours alone compare endurance without voltage or load information.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「備援電源與能量帳」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Backup power and energy budget”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b269-v15-33-k1","title":"備援電源與能量帳機理與驗證","titleEn":"Backup power and energy budget mechanism and verification","text":"偏遠測站的可用時間取決於平均負載、通訊脈衝、電池可用容量及環境條件，不能只看安培小時數。電壓換算、允許放電深度和電源轉換損失都影響可用能量，低溫與老化又可能降低容量；太陽能日均供電也無法單獨保證連續陰雨期間仍有資料。","textEn":"Remote-station endurance depends on average load, transmission pulses, usable battery capacity and environment rather than ampere-hours alone. Voltage, allowed depth of discharge and conversion losses determine useful energy, while cold and aging may reduce capacity.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：電池安培小時越大就可直接比較續航，不需要知道電壓或負載。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Battery ampere-hours alone compare endurance without voltage or load information. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"關於「備援電源與能量帳機理與驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Backup power and energy budget mechanism and verification\" is correct?","options":["偏遠測站的可用時間取決於平均負載、通訊脈衝、電池可用容量及環境條件，不能只看安培小時數。","電池安培小時越大就可直接比較續航，不需要知道電壓或負載。","只要現場裝兩支感測器，就一定可以把全部失效機率相乘。"],"optionsEn":["Remote-station endurance depends on average load, transmission pulses, usable battery capacity and environment rather than ampere-hours alone.","Battery ampere-hours alone compare endurance without voltage or load information.","Installing two field sensors always permits multiplication of all failure probabilities."],"answer":0,"explanation":"偏遠測站的可用時間取決於平均負載、通訊脈衝、電池可用容量及環境條件，不能只看安培小時數。 其餘選項是常見誤解。","explanationEn":"Remote-station endurance depends on average load, transmission pulses, usable battery capacity and environment rather than ampere-hours alone. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b269-v15-34","title":"備援電源與能量帳機理與驗證：定量估算","titleEn":"Backup power and energy budget mechanism and verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-33"],"objective":"以數值模型估算「備援電源與能量帳」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Backup power and energy budget” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設算例，以下量值用於簡化機理比較：假設電池12 V、40 Ah、可用放電比例0.50、轉換效率0.85、平均負載2 W，續航t=12×40×0.50×0.85/2=102 h。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume battery 12 V, 40 Ah, usable discharge fraction 0.50, conversion efficiency 0.85 and mean load 2 W. Endurance t=12×40×0.50×0.85/2=102 h. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：量測感測、待機和傳輸各狀態功率及占空比，將短時峰值和平均能量分開核對。","observationEn":"How to cross-check: Measure sensing, standby and transmission power with duty cycles, checking peak demand separately from average energy.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b269-v15-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設算例，以下量值用於簡化機理比較：假設電池12 V、40 Ah、可用放電比例0.50、轉換效率0.85、平均負載2 W，續航t=12×40×0.50×0.85/2=102 h。","textEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume battery 12 V, 40 Ah, usable discharge fraction 0.50, conversion efficiency 0.85 and mean load 2 W. Endurance t=12×40×0.50×0.85/2=102 h.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"依「備援電源與能量帳機理與驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Backup power and energy budget mechanism and verification\", which statement holds?","options":["任何壓力感測器輸出除以水重度就一定得到真實河川水深。","原創教學假設算例，以下量值用於簡化機理比較：假設電池12 V、40 Ah、可用放電比例0.50、轉換效率0.85、平均負載2 W，續航t=12×40×0.50×0.85/2=102 h。","只要圖表每秒重畫，就代表河川每秒都有一筆新量測。"],"optionsEn":["Any pressure output divided by water unit weight gives true river depth.","Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume battery 12 V, 40 Ah, usable discharge fraction 0.50, conversion efficiency 0.85 and mean load 2 W.","A graph refreshed every second means the river has a new measurement every second."],"answer":1,"explanation":"原創教學假設算例，以下量值用於簡化機理比較：假設電池12 V、40 Ah、可用放電比例0.50、轉換效率0.85、平均負載2 W，續航t=12×40×0.50×0.85/2=102 h。 重算時請保留單位。","explanationEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume battery 12 V, 40 Ah, usable discharge fraction 0.50, conversion efficiency 0.85 and mean load 2 W. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":34},{"id":"b269-v15-35","title":"備援電源與能量帳機理與驗證：試驗與驗證","titleEn":"Backup power and energy budget mechanism and verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「備援電源與能量帳」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Backup power and energy budget” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"量測感測、待機和傳輸各狀態功率及占空比，將短時峰值和平均能量分開核對。以老化與低溫容量資料更新可用量，並用中斷充電的測試確認低電量標示及資料保存行為。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure sensing, standby and transmission power with duty cycles, checking peak demand separately from average energy. Update usable capacity with aging and temperature evidence, and test interrupted charging to confirm low-battery indication and preservation of observations before power is exhausted. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將通訊占空比增加一倍後重算平均負載，再比較低溫容量下降情境。為能量耗盡前後設計資料旗標，區分感測中斷、通訊中斷和仍可本地記錄的狀態。","observationEn":"Site practice: Double communication duty cycle and recalculate mean load, then compare reduced cold-weather capacity. Define data flags around energy exhaustion that distinguish sensing failure, communication loss and continued local recording.","failure":"注意干擾：忽略傳輸峰值可能使電池尚有能量卻因瞬時壓降重啟，使用新電池容量估計老站又會高估續航；斷電後無明確旗標可能被誤解為河水停止變化。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Ignoring transmission peaks can cause reset from voltage sag despite remaining energy. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b269-v15-35-k1","title":"驗證方法","titleEn":"Verification method","text":"量測感測、待機和傳輸各狀態功率及占空比，將短時峰值和平均能量分開核對。以老化與低溫容量資料更新可用量，並用中斷充電的測試確認低電量標示及資料保存行為。","textEn":"Measure sensing, standby and transmission power with duty cycles, checking peak demand separately from average energy. Update usable capacity with aging and temperature evidence, and test interrupted charging to confirm low-battery indication and preservation of observations before power is exhausted.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-35-k2","title":"現場實務","titleEn":"Site practice","text":"將通訊占空比增加一倍後重算平均負載，再比較低溫容量下降情境。為能量耗盡前後設計資料旗標，區分感測中斷、通訊中斷和仍可本地記錄的狀態。","textEn":"Double communication duty cycle and recalculate mean load, then compare reduced cold-weather capacity. Define data flags around energy exhaustion that distinguish sensing failure, communication loss and continued local recording.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"要驗證「備援電源與能量帳機理與驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Backup power and energy budget mechanism and verification\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","裝好水位計後，任何洪水流量都能無誤差地自動換算。","量測感測、待機和傳輸各狀態功率及占空比，將短時峰值和平均能量分開核對。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Once a stage sensor is installed, every flood discharge converts automatically without error.","Measure sensing, standby and transmission power with duty cycles, checking peak demand separately from average energy."],"answer":2,"explanation":"量測感測、待機和傳輸各狀態功率及占空比，將短時峰值和平均能量分開核對。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure sensing, standby and transmission power with duty cycles, checking peak demand separately from average energy. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":35},{"id":"b269-v15-36","title":"備援電源與能量帳機理與驗證：失效診斷","titleEn":"Backup power and energy budget mechanism and verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-35"],"objective":"從症狀倒推「備援電源與能量帳」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Backup power and energy budget” and propose discriminating checks, corrective actions and prevention.","instruction":"忽略傳輸峰值可能使電池尚有能量卻因瞬時壓降重啟，使用新電池容量估計老站又會高估續航；斷電後無明確旗標可能被誤解為河水停止變化。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Ignoring transmission peaks can cause reset from voltage sag despite remaining energy. Using new-battery capacity for an aged station overstates endurance, and missing outage flags can make power failure look like unchanging river stage. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：本例以固定平均負載與指定可用係數作能量比較，忽略自放電、老化和低溫；計算時數不是實站續航保證。","observationEn":"Link to the mechanism: Calculated hours are an energy comparison, not a station-endurance guarantee.","failure":"誤判風險：若相信「電池安培小時越大就可直接比較續航，不需要知道電壓或負載。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Battery ampere-hours alone compare endurance without voltage or load information.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b269-v15-36-k1","title":"失效模式","titleEn":"Failure mode","text":"忽略傳輸峰值可能使電池尚有能量卻因瞬時壓降重啟，使用新電池容量估計老站又會高估續航；斷電後無明確旗標可能被誤解為河水停止變化。","textEn":"Ignoring transmission peaks can cause reset from voltage sag despite remaining energy. Using new-battery capacity for an aged station overstates endurance, and missing outage flags can make power failure look like unchanging river stage.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"在「備援電源與能量帳機理與驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Backup power and energy budget mechanism and verification\" shows distress, which diagnosis is most reasonable?","options":["忽略傳輸峰值可能使電池尚有能量卻因瞬時壓降重啟，使用新電池容量估計老站又會高估續航；斷電後無明確旗標可能被誤解為河水停止變化。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","只要現場裝兩支感測器，就一定可以把全部失效機率相乘。"],"optionsEn":["Ignoring transmission peaks can cause reset from voltage sag despite remaining energy.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Installing two field sensors always permits multiplication of all failure probabilities."],"answer":0,"explanation":"忽略傳輸峰值可能使電池尚有能量卻因瞬時壓降重啟，使用新電池容量估計老站又會高估續航；斷電後無明確旗標可能被誤解為河水停止變化。 需以量測區分可能原因。","explanationEn":"Ignoring transmission peaks can cause reset from voltage sag despite remaining energy. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":36},{"id":"b269-v15-37","title":"獨立備援與共因失效機理與驗證：機制與系統路徑","titleEn":"Independent redundancy and common causes mechanism and verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-36"],"objective":"說明「獨立備援與共因失效」如何影響河川水位自動遙測的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Independent redundancy and common causes” governs forces, deformation, flow or signals in “Automatic river-level telemetry”, and map the relevant inputs, transfer paths and boundaries.","instruction":"兩套感測或通訊可提高資料可用性，但只有真正獨立的失效才可直接相乘。若共用電源、支架、基準點或被同一洪水淹沒，備援仍可能同時失效；不同技術也可能共享資料伺服器，應沿整條量測到發布路徑辨認共因，而不是只數現場儀器數量。本例定義相同觀察期間兩通道失效機率且假設獨立，只示範理想備援；未加入修復、共因及不同失效模式。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「獨立備援與共因失效」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Two sensors or links can improve availability, but failure probabilities multiply only for independent events. Shared power, support, datum or flood exposure can disable both. Different sensing technologies may still share a publication server, so common causes must be traced through the complete observation-to-display chain rather than inferred from device count. The example defines channel-failure probabilities over the same observation period and assumes independence. It illustrates ideal redundancy without repair, common causes or multiple failure modes. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Independent redundancy and common causes” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設算例，以下量值用於簡化機理比較：假設兩通道期間失效機率p1=p2=0.02且獨立，同時失效p=p1p2=0.0004，即0.04%。","observationEn":"Order-of-magnitude cue: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume independent channel-failure probabilities p1=p2=0.02 over the same period.","failure":"常見誤解：「只要現場裝兩支感測器，就一定可以把全部失效機率相乘。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Installing two field sensors always permits multiplication of all failure probabilities.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「獨立備援與共因失效」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Independent redundancy and common causes”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b269-v15-37-k1","title":"獨立備援與共因失效機理與驗證","titleEn":"Independent redundancy and common causes mechanism and verification","text":"兩套感測或通訊可提高資料可用性，但只有真正獨立的失效才可直接相乘。若共用電源、支架、基準點或被同一洪水淹沒，備援仍可能同時失效；不同技術也可能共享資料伺服器，應沿整條量測到發布路徑辨認共因，而不是只數現場儀器數量。","textEn":"Two sensors or links can improve availability, but failure probabilities multiply only for independent events. Shared power, support, datum or flood exposure can disable both.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要現場裝兩支感測器，就一定可以把全部失效機率相乘。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Installing two field sensors always permits multiplication of all failure probabilities. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"關於「獨立備援與共因失效機理與驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Independent redundancy and common causes mechanism and verification\" is correct?","options":["只要現場裝兩支感測器，就一定可以把全部失效機率相乘。","兩套感測或通訊可提高資料可用性，但只有真正獨立的失效才可直接相乘。","所有水位計顯示的公尺數都已是同一海拔基準下的高程。"],"optionsEn":["Installing two field sensors always permits multiplication of all failure probabilities.","Two sensors or links can improve availability, but failure probabilities multiply only for independent events.","Every water-level reading in meters already uses the same sea-level datum."],"answer":1,"explanation":"兩套感測或通訊可提高資料可用性，但只有真正獨立的失效才可直接相乘。 其餘選項是常見誤解。","explanationEn":"Two sensors or links can improve availability, but failure probabilities multiply only for independent events. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b269-v15-38","title":"獨立備援與共因失效機理與驗證：定量估算","titleEn":"Independent redundancy and common causes mechanism and verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-37"],"objective":"以數值模型估算「獨立備援與共因失效」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Independent redundancy and common causes” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設算例，以下量值用於簡化機理比較：假設兩通道期間失效機率p1=p2=0.02且獨立，同時失效p=p1p2=0.0004，即0.04%。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume independent channel-failure probabilities p1=p2=0.02 over the same period. Joint failure p=p1p2=0.0004, or 0.04%. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：畫出感測、電源、通訊與發布的依賴圖，逐項尋找共用構件和洪水暴露。","observationEn":"How to cross-check: Map dependencies among sensing, power, communication and publication, identifying shared components and flood exposure.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b269-v15-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設算例，以下量值用於簡化機理比較：假設兩通道期間失效機率p1=p2=0.02且獨立，同時失效p=p1p2=0.0004，即0.04%。","textEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume independent channel-failure probabilities p1=p2=0.02 over the same period. Joint failure p=p1p2=0.0004, or 0.04%.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"依「獨立備援與共因失效機理與驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Independent redundancy and common causes mechanism and verification\", which statement holds?","options":["雷達不接觸水，所以不需要高程測量或現地水尺交叉驗證。","封包剛收到就一定代表此刻水位，無需再看量測時間。","原創教學假設算例，以下量值用於簡化機理比較：假設兩通道期間失效機率p1=p2=0.02且獨立，同時失效p=p1p2=0.0004，即0.04%。"],"optionsEn":["Noncontact radar needs neither elevation surveying nor field staff-gage checks.","A newly received packet necessarily represents current stage without checking observation time.","Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume independent channel-failure probabilities p1=p2=0.02 over the same period."],"answer":2,"explanation":"原創教學假設算例，以下量值用於簡化機理比較：假設兩通道期間失效機率p1=p2=0.02且獨立，同時失效p=p1p2=0.0004，即0.04%。 重算時請保留單位。","explanationEn":"Original teaching example using hypothetical inputs to compare a simplified physical mechanism: Assume independent channel-failure probabilities p1=p2=0.02 over the same period. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":38},{"id":"b269-v15-39","title":"獨立備援與共因失效機理與驗證：試驗與驗證","titleEn":"Independent redundancy and common causes mechanism and verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「獨立備援與共因失效」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Independent redundancy and common causes” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"畫出感測、電源、通訊與發布的依賴圖，逐項尋找共用構件和洪水暴露。以受控故障測試確認切換、補傳與資料旗標，並用實際事件記錄評估獨立假設是否成立。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Map dependencies among sensing, power, communication and publication, identifying shared components and flood exposure. Use controlled failure tests to check switching, backfill and quality flags, then examine event records to assess whether the assumed independence is supported rather than merely convenient. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：為雙感測器畫出共用與獨立電源兩個架構，指出哪些故障可由另一通道保留觀測。加入共同淹水事件後重新描述模型限制，避免把理想數字當保證。","observationEn":"Site practice: Draw shared- and independent-power versions of a dual-sensor system, identifying failures that leave observations available. Add a common inundation event and restate the model limits rather than presenting the ideal probability as a guarantee.","failure":"注意干擾：共用電源的雙感測器可能一次斷電全部停擺，雙通訊也可能同時依賴同一伺服器；直接乘機率會給出過度樂觀的可用性，卻沒有增加真正的失效隔離。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Two sensors on one supply can fail in a single outage, and two links may depend on the same server. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b269-v15-39-k1","title":"驗證方法","titleEn":"Verification method","text":"畫出感測、電源、通訊與發布的依賴圖，逐項尋找共用構件和洪水暴露。以受控故障測試確認切換、補傳與資料旗標，並用實際事件記錄評估獨立假設是否成立。","textEn":"Map dependencies among sensing, power, communication and publication, identifying shared components and flood exposure. Use controlled failure tests to check switching, backfill and quality flags, then examine event records to assess whether the assumed independence is supported rather than merely convenient.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-39-k2","title":"現場實務","titleEn":"Site practice","text":"為雙感測器畫出共用與獨立電源兩個架構，指出哪些故障可由另一通道保留觀測。加入共同淹水事件後重新描述模型限制，避免把理想數字當保證。","textEn":"Draw shared- and independent-power versions of a dual-sensor system, identifying failures that leave observations available. Add a common inundation event and restate the model limits rather than presenting the ideal probability as a guarantee.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"要驗證「獨立備援與共因失效機理與驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Independent redundancy and common causes mechanism and verification\"?","options":["畫出感測、電源、通訊與發布的依賴圖，逐項尋找共用構件和洪水暴露。","不確定度太難估計，報告中只寫最佳值即可。","取樣越密，任何相鄰兩點差分得到的水位速率就一定越可靠。"],"optionsEn":["Map dependencies among sensing, power, communication and publication, identifying shared components and flood exposure.","Uncertainty is too hard to estimate, so the report may state only the best value.","Denser sampling always makes a two-point stage derivative more reliable."],"answer":0,"explanation":"畫出感測、電源、通訊與發布的依賴圖，逐項尋找共用構件和洪水暴露。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Map dependencies among sensing, power, communication and publication, identifying shared components and flood exposure. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":39},{"id":"b269-v15-40","title":"獨立備援與共因失效機理與驗證：失效診斷","titleEn":"Independent redundancy and common causes mechanism and verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"prerequisiteIds":["b269-v15-39"],"objective":"從症狀倒推「獨立備援與共因失效」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Independent redundancy and common causes” and propose discriminating checks, corrective actions and prevention.","instruction":"共用電源的雙感測器可能一次斷電全部停擺，雙通訊也可能同時依賴同一伺服器；直接乘機率會給出過度樂觀的可用性，卻沒有增加真正的失效隔離。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Two sensors on one supply can fail in a single outage, and two links may depend on the same server. Multiplying probabilities then gives optimistic availability without genuine isolation of the failure mechanisms. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：本例定義相同觀察期間兩通道失效機率且假設獨立，只示範理想備援；未加入修復、共因及不同失效模式。","observationEn":"Link to the mechanism: It illustrates ideal redundancy without repair, common causes or multiple failure modes.","failure":"誤判風險：若相信「只要現場裝兩支感測器，就一定可以把全部失效機率相乘。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Installing two field sensors always permits multiplication of all failure probabilities.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b269-v15-40-k1","title":"失效模式","titleEn":"Failure mode","text":"共用電源的雙感測器可能一次斷電全部停擺，雙通訊也可能同時依賴同一伺服器；直接乘機率會給出過度樂觀的可用性，卻沒有增加真正的失效隔離。","textEn":"Two sensors on one supply can fail in a single outage, and two links may depend on the same server. Multiplying probabilities then gives optimistic availability without genuine isolation of the failure mechanisms.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]},{"id":"b269-v15-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"]}],"quiz":{"question":"在「獨立備援與共因失效機理與驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Independent redundancy and common causes mechanism and verification\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","共用電源的雙感測器可能一次斷電全部停擺，雙通訊也可能同時依賴同一伺服器；直接乘機率會給出過度樂觀的可用性，卻沒有增加真正的失效隔離。","所有水位計顯示的公尺數都已是同一海拔基準下的高程。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Two sensors on one supply can fail in a single outage, and two links may depend on the same server.","Every water-level reading in meters already uses the same sea-level datum."],"answer":1,"explanation":"共用電源的雙感測器可能一次斷電全部停擺，雙通訊也可能同時依賴同一伺服器；直接乘機率會給出過度樂觀的可用性，卻沒有增加真正的失效隔離。 需以量測區分可能原因。","explanationEn":"Two sensors on one supply can fail in a single outage, and two links may depend on the same server. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":40}],"order":5}],"sourceIds":["v15s-usgs-stage","v15s-usgs-levels","v15s-usgs-lees","v15s-usgs-vicksburg","v15s-noaa-dcs"],"curriculumVersion":15,"stepCount":40,"estimatedMinutes":1000}};
